// FAQ Questions and Answers
faq_q1: "मैं गोफार्मलीकनेक्ट पर अपने खेत को कैसे पंजीकृत करूँ?",
faq_a1:
  "पंजीकरण सरल और मुफ्त है। 'शुरू करें' पर क्लिक करें, अपने खेत का मूल विवरण भरें, आवश्यक दस्तावेज़ अपलोड करें, और अपने मोबाइल नंबर को सत्यापित करें। हमारी टीम 24 घंटे के भीतर आपके खाते की समीक्षा और सक्रिय करेगी।",
faq_q2: "मैं इस मंच के माध्यम से कौन से दस्तावेज़ दाखिल कर सकता हूँ?",
faq_a2:
  "आप फसल बीमा आवेदन, सब्सिडी फॉर्म, ऋण आवेदन, भूमि रिकॉर्ड, मिट्टी स्वास्थ्य कार्ड, और अनुपालन प्रमाणपत्र सहित सभी प्रमुख कृषि दस्तावेज़ दाखिल कर सकते हैं। हमारा सिस्टम 50+ दस्तावेज़ प्रकारों का समर्थन करता है।",
faq_q3: "क्या मेरा डेटा गोफार्मलीकनेक्ट पर सुरक्षित है?",
faq_a3:
  "बिल्कुल। हम बैंक-ग्रेड एन्क्रिप्शन का उपयोग करते हैं और सख्त डेटा संरक्षण प्रोटोकॉल का पालन करते हैं। आपकी जानकारी सुरक्षित रूप से संग्रहीत की जाती है और आपकी सहमति के बिना तीसरे पक्ष के साथ साझा नहीं की जाती। हम सभी सरकारी डेटा संरक्षण नियमों का भी पालन करते हैं।",
faq_q4: "फसल उपज भविष्यवाणियों की सटीकता कितनी है?",
faq_a4:
  "हमारी एआई-संचालित भविष्यवाणियों की सटीकता दर 85-90% है। हम उपग्रह चित्रण, मौसम डेटा, मिट्टी की स्थिति, और ऐतिहासिक पैटर्न का उपयोग करके विश्वसनीय पूर्वानुमान प्रदान करते हैं। हालांकि, भविष्यवाणियों को आपकी खेती विशेषज्ञता के साथ मार्गदर्शन के रूप में उपयोग करना चाहिए।",
faq_q5: "क्या मैं गोफार्मलीकनेक्ट को ऑफलाइन उपयोग कर सकता हूँ?",
faq_a5:
  "हाँ, हमारे मोबाइल ऐप में ऑफलाइन क्षमताएँ हैं। आप अपने डेटा को देख सकते हैं, फॉर्म भर सकते हैं, और इंटरनेट के बिना ट्यूटोरियल तक पहुँच सकते हैं। एक बार जब आप ऑनलाइन वापस आते हैं, तो सभी परिवर्तन स्वचालित रूप से क्लाउड के साथ समन्वयित हो जाते हैं।",
faq_q6: "इसमें कितना खर्च आता है?",
faq_a6:
  "मूल सुविधाएँ सभी किसानों के लिए पूरी तरह मुफ्त हैं। उन्नत विश्लेषण, प्राथमिकता समर्थन, और अतिरिक्त भंडारण जैसी प्रीमियम सुविधाएँ ₹99/माह से शुरू होने वाली किफायती सदस्यता योजनाओं के माध्यम से उपलब्ध हैं।",
faq_q7: "मुझे तकनीकी समर्थन कैसे मिलेगा?",
faq_a7:
  "हम फोन (1800-3010-1000), ईमेल, लाइव चैट, और व्हाट्सएप के माध्यम से 24/7 समर्थन प्रदान करते हैं। हमारे कृषि विशेषज्ञ किसी भी तकनीकी या खेती से संबंधित प्रश्नों में आपकी मदद के लिए हमेशा तैयार हैं।",
faq_q8: "क्या मैं गोफार्मलीकनेक्ट को अन्य खेती उपकरणों के साथ एकीकृत कर सकता हूँ?",
faq_a8:
  "हाँ, गोफार्मलीकनेक्ट लोकप्रिय खेती उपकरणों, मौसम स्टेशनों, और वित्तीय सेवाओं के साथ एकीकृत होता है। हमारे पास कस्टम एकीकरण और प्रमुख कृषि प्रौद्योगिकी प्रदाताओं के साथ साझेदारी के लिए API उपलब्ध हैं।",

