// IEC Information
what_is_iec: "आईईसी क्या है?",
iec_description_1: "आईईसी (आयात निर्यात कोड) डीजीएफटी द्वारा जारी किया गया 10-अंकीय अल्फान्यूमेरिक कोड है।",
iec_description_2: "यह भारत में आयात या निर्यात व्यवसाय में लगे व्यक्तियों/इकाइयों के लिए अनिवार्य है।",
iec_description_3: "सीमा शुल्क निकासी, विदेशी मुद्रा लेनदेन, और अंतरराष्ट्रीय व्यापार के लिए आवश्यक है।",
iec_description_4: "आजीवन वैध, नवीकरण की आवश्यकता नहीं।",
benefits_of_iec_registration: "आईईसी पंजीकरण के लाभ:",
iec_benefit_1: "आयात और निर्यात के लिए अंतरराष्ट्रीय व्यापार कार्यों को सक्षम करता है।",
iec_benefit_2: "डीजीएफटी से निर्यात प्रोत्साहन और योजनाओं तक पहुंच।",
iec_benefit_3: "सीमा शुल्क प्रक्रियाओं और दस्तावेज़ीकरण को सरल बनाता है।",
