// FAQ Questions and Answers
faq_q1: "ਮੈਂ ਗੋਫਾਰਮਲੀਕਨੈਕਟ 'ਤੇ ਆਪਣਾ ਫਾਰਮ ਕਿਵੇਂ ਰਜਿਸਟਰ ਕਰਾਂ?",
faq_a1:
  "ਰਜਿਸਟ੍ਰੇਸ਼ਨ ਸਰਲ ਅਤੇ ਮੁਫਤ ਹੈ। 'ਸ਼ੁਰੂ ਕਰੋ' 'ਤੇ ਕਲਿੱਕ ਕਰੋ, ਆਪਣੇ ਮੁੱਢਲੇ ਫਾਰਮ ਵੇਰਵੇ ਭਰੋ, ਲੋੜੀਂਦੇ ਦਸਤਾਵੇਜ਼ ਅਪਲੋਡ ਕਰੋ, ਅਤੇ ਆਪਣਾ ਮੋਬਾਈਲ ਨੰਬਰ ਪ੍ਰਮਾਣਿਤ ਕਰੋ। ਸਾਡੀ ਟੀਮ 24 ਘੰਟਿਆਂ ਦੇ ਅੰਦਰ ਤੁਹਾਡੇ ਖਾਤੇ ਦੀ ਸਮੀਖਿਆ ਅਤੇ ਸਰਗਰਮ ਕਰੇਗੀ।",
faq_q2: "ਮੈਂ ਪਲੇਟਫਾਰਮ ਰਾਹੀਂ ਕਿਹੜੇ ਦਸਤਾਵੇਜ਼ ਫਾਈਲ ਕਰ ਸਕਦਾ ਹਾਂ?",
faq_a2:
  "ਤੁਸੀਂ ਫਸਲ ਬੀਮਾ ਅਰਜ਼ੀਆਂ, ਸਬਸਿਡੀ ਫਾਰਮ, ਲੋਨ ਅਰਜ਼ੀਆਂ, ਜ਼ਮੀਨ ਦੇ ਰਿਕਾਰਡ, ਮਿੱਟੀ ਸਿਹਤ ਕਾਰਡ, ਅਤੇ ਅਨੁਪਾਲਨ ਸਰਟੀਫਿਕੇਟ ਸਮੇਤ ਸਾਰੇ ਪ੍ਰਮੁੱਖ ਖੇਤੀਬਾੜੀ ਦਸਤਾਵੇਜ਼ ਫਾਈਲ ਕਰ ਸਕਦੇ ਹੋ। ਸਾਡਾ ਸਿਸਟਮ 50+ ਤੋਂ ਵੱਧ ਦਸਤਾਵੇਜ਼ ਕਿਸਮਾਂ ਦਾ ਸਮਰਥਨ ਕਰਦਾ ਹੈ।",
faq_q3: "ਕੀ ਮੇਰਾ ਡੇਟਾ ਗੋਫਾਰਮਲੀਕਨੈਕਟ 'ਤੇ ਸੁਰੱਖਿਅਤ ਹੈ?",
faq_a3:
  "ਬਿਲਕੁਲ। ਅਸੀਂ ਬੈਂਕ-ਗ੍ਰੇਡ ਐਨਕ੍ਰਿਪਸ਼ਨ ਅਤੇ ਸਖਤ ਡੇਟਾ ਸੁਰੱਖਿਆ ਪ੍ਰੋਟੋਕੋਲ ਦੀ ਵਰਤੋਂ ਕਰਦੇ ਹਾਂ। ਤੁਹਾਡੀ ਜਾਣਕਾਰੀ ਸੁਰੱਖਿਅਤ ਢੰਗ ਨਾਲ ਸਟੋਰ ਕੀਤੀ ਜਾਂਦੀ ਹੈ ਅਤੇ ਤੁਹਾਡੀ ਸਹਿਮਤੀ ਤੋਂ ਬਿਨਾਂ ਕਦੇ ਵੀ ਤੀਜੀ ਧਿਰ ਨਾਲ ਸਾਂਝੀ ਨਹੀਂ ਕੀਤੀ ਜਾਂਦੀ। ਅਸੀਂ ਸਾਰੀਆਂ ਸਰਕਾਰੀ ਡੇਟਾ ਸੁਰੱਖਿਆ ਨਿਯਮਾਂ ਦੀ ਪਾਲਣਾ ਵੀ ਕਰਦੇ ਹਾਂ।",
faq_q4: "ਫਸਲ ਉਪਜ ਦੀਆਂ ਭਵਿੱਖਬਾਣੀਆਂ ਕਿੰਨੀਆਂ ਸਹੀ ਹਨ?",
faq_a4:
  "ਸਾਡੀਆਂ AI-ਸੰਚਾਲਿਤ ਭਵਿੱਖਬਾਣੀਆਂ ਦੀ ਸ਼ੁੱਧਤਾ ਦਰ 85-90% ਹੈ। ਅਸੀਂ ਸੈਟੇਲਾਈਟ ਚਿੱਤਰਾਂ, ਮੌਸਮ ਡੇਟਾ, ਮਿੱਟੀ ਦੀਆਂ ਸਥਿਤੀਆਂ, ਅਤੇ ਇਤਿਹਾਸਕ ਪੈਟਰਨਾਂ ਦੀ ਵਰਤੋਂ ਕਰਕੇ ਭਰੋਸੇਯੋਗ ਪੂਰਵ ਅਨੁਮਾਨ ਪ੍ਰਦਾਨ ਕਰਦੇ ਹਾਂ। ਹਾਲਾਂਕਿ, ਭਵਿੱਖਬਾਣੀਆਂ ਨੂੰ ਤੁਹਾਡੀ ਖੇਤੀਬਾੜੀ ਮੁਹਾਰਤ ਦੇ ਨਾਲ ਮਾਰਗਦਰਸ਼ਨ ਵਜੋਂ ਵਰਤਿਆ ਜਾਣਾ ਚਾਹੀਦਾ ਹੈ।",
faq_q5: "ਕੀ ਮੈਂ ਗੋਫਾਰਮਲੀਕਨੈਕਟ ਨੂੰ ਆਫਲਾਈਨ ਵਰਤ ਸਕਦਾ ਹਾਂ?",
faq_a5:
  "ਹਾਂ, ਸਾਡੀ ਮੋਬਾਈਲ ਐਪ ਵਿੱਚ ਆਫਲਾਈਨ ਸਮਰੱਥਾਵਾਂ ਹਨ। ਤੁਸੀਂ ਬਿਨਾਂ ਇੰਟਰਨੈਟ ਦੇ ਆਪਣਾ ਡੇਟਾ ਦੇਖ ਸਕਦੇ ਹੋ, ਫਾਰਮ ਭਰ ਸਕਦੇ ਹੋ, ਅਤੇ ਟਿਊਟੋਰੀਅਲ ਤੱਕ ਪਹੁੰਚ ਕਰ ਸਕਦੇ ਹੋ। ਜਦੋਂ ਤੁਸੀਂ ਦੁਬਾਰਾ ਔਨਲਾਈਨ ਹੋਵੋ, ਸਾਰੀਆਂ ਤਬਦੀਲੀਆਂ ਸਵੈਚਾਲਤ ਤੌਰ 'ਤੇ ਕਲਾਉਡ ਨਾਲ ਸਿੰਕ ਹੋ ਜਾਂਦੀਆਂ ਹਨ।",
faq_q6: "ਇਸ ਵਿੱਚ ਕੀ ਖਰਚੇ ਸ਼ਾਮਲ ਹਨ?",
faq_a6:
  "ਮੁੱਢਲੀਆਂ ਵਿਸ਼ੇਸ਼ਤਾਵਾਂ ਸਾਰੇ ਕਿਸਾਨਾਂ ਲਈ ਪੂਰੀ ਤਰ੍ਹਾਂ ਮੁਫਤ ਹਨ। ਉੱਨਤ ਵਿਸ਼ਲੇਸ਼ਣ, ਪ੍ਰਾਈਓਰਿਟੀ ਸਹਾਇਤਾ, ਅਤੇ ਵਾਧੂ ਸਟੋਰੇਜ ਵਰਗੀਆਂ ਪ੍ਰੀਮੀਅਮ ਵਿਸ਼ੇਸ਼ਤਾਵਾਂ ₹99/ਮਹੀਨੇ ਤੋਂ ਸ਼ੁਰੂ ਹੋਣ ਵਾਲੇ ਸਸਤੇ ਸਬਸਕ੍ਰਿਪਸ਼ਨ ਪਲਾਨਾਂ ਰਾਹੀਂ ਉਪਲਬਧ ਹਨ।",
faq_q7: "ਮੈਂ ਤਕਨੀਕੀ ਸਹਾਇਤਾ ਕਿਵੇਂ ਪ੍ਰਾਪਤ ਕਰ ਸਕਦਾ ਹਾਂ?",
faq_a7:
  "ਅਸੀਂ ਫੋਨ (1800-3010-1000), ਈਮੇਲ, ਲਾਈਵ ਚੈਟ, ਅਤੇ ਵਟਸਐਪ ਰਾਹੀਂ 24/7 ਸਹਾਇਤਾ ਪ੍ਰਦਾਨ ਕਰਦੇ ਹਾਂ। ਸਾਡੇ ਖੇਤੀਬਾੜੀ ਮਾਹਰ ਕਿਸੇ ਵੀ ਤਕਨੀਕੀ ਜਾਂ ਖੇਤੀਬਾੜੀ-ਸਬੰਧਤ ਸਵਾਲਾਂ ਲਈ ਤੁਹਾਡੀ ਮਦਦ ਕਰਨ ਲਈ ਹਮੇਸ਼ਾ ਤਿਆਰ ਹਨ।",
faq_q8: "ਕੀ ਮੈਂ ਗੋਫਾਰਮਲੀਕਨੈਕਟ ਨੂੰ ਹੋਰ ਖੇਤੀਬਾੜੀ ਸਾਧਨਾਂ ਨਾਲ ਜੋੜ ਸਕਦਾ ਹਾਂ?",
faq_a8:
  "ਹਾਂ, ਗੋਫਾਰਮਲੀਕਨੈਕਟ ਪ੍ਰਸਿੱਧ ਖੇਤੀਬਾੜੀ ਉਪਕਰਣਾਂ, ਮੌਸਮ ਸਟੇਸ਼ਨਾਂ, ਅਤੇ ਵਿੱਤੀ ਸੇਵਾਵਾਂ ਨਾਲ ਜੁੜਦਾ ਹੈ। ਸਾਡੇ ਕੋਲ ਕਸਟਮ ਏਕੀਕਰਣ ਅਤੇ ਪ੍ਰਮੁੱਖ ਖੇਤੀਬਾੜੀ ਤਕਨੀਕ ਪ੍ਰਦਾਤਾਵਾਂ ਨਾਲ ਸਾਂਝੇਦਾਰੀਆਂ ਲਈ APIs ਉਪਲਬਧ ਹਨ।",

