icegate_definition_4: "• ਭਾਰਤੀ ਕਸਟਮਜ਼ ਨਾਲ ਸੰਪਰਕ ਕਰਨ ਲਈ ਆਯਾਤਕਾਂ ਅਤੇ ਨਿਰਯਾਤਕਾਂ ਲਈ ਜ਼ਰੂਰੀ",
benefits_of_icegate: "📋 ਆਈਸੀਈਗੇਟ ਰਜਿਸਟ੍ਰੇਸ਼ਨ ਦੇ ਫਾਇਦੇ:",
icegate_benefit_1: "• ਸੁਚਾਰੂ ਕਸਟਮਜ਼ ਕਲੀਅਰੈਂਸ ਪ੍ਰਕਿਰਿਆ",
icegate_benefit_2: "• ਆਯਾਤ ਅਤੇ ਨਿਰਯਾਤ ਖੇਪਾਂ ਦੀ ਤੇਜ਼ ਪ੍ਰੋਸੈਸਿੰਗ",
icegate_benefit_3: "• ਕਸਟਮਜ਼ ਡੇਟਾ ਅਤੇ ਸਥਿਤੀ ਅਪਡੇਟਸ ਤੱਕ ਔਨਲਾਈਨ ਪਹੁੰਚ",
icegate_benefit_4: "• ਘਟਿਆ ਪੇਪਰਵਰਕ ਅਤੇ ਮੈਨੂਅਲ ਦਖਲ",
