    "copyright_text": "© 2025 ਗੋਫਾਰਮਲੀਕਨੈਕਟ - ਤਕਨਾਲੋਜੀ ਦੁਆਰਾ ਖੇਤੀਬਾੜੀ ਨੂੰ ਬਦਲਣਾ। ਸਾਰੇ ਅਧਿਕਾਰ ਸੁਰੱਖਿਅਤ।",
