    // FAQ Questions and Answers
    "faq_q1": "ਮੈਂ ਗੋਫਾਰਮਲੀਕਨੈਕਟ 'ਤੇ ਆਪਣਾ ਫਾਰਮ ਕਿਵੇਂ ਰਜਿਸਟਰ ਕਰਾਂ?",
    "faq_a1": "ਰਜਿਸਟ੍ਰੇਸ਼ਨ ਸਰਲ ਅਤੇ ਮੁਫਤ ਹੈ। 'ਸ਼ੁਰੂ ਕਰੋ' 'ਤੇ ਕਲਿੱਕ ਕਰੋ, ਆਪਣੇ ਮੁੱਢਲੇ ਫਾਰਮ ਵੇਰਵੇ ਭਰੋ, ਲੋੜੀਂਦੇ ਦਸਤਾਵੇਜ਼ ਅਪਲੋਡ ਕਰੋ, ਅਤੇ ਆਪਣਾ ਮੋਬਾਈਲ ਨੰਬਰ ਪ੍ਰਮਾਣਿਤ ਕਰੋ। ਸਾਡੀ ਟੀਮ 24 ਘੰਟਿਆਂ ਦੇ ਅੰਦਰ ਤੁਹਾਡੇ ਖਾਤੇ ਦੀ ਸਮੀਖਿਆ ਅਤੇ ਸਰਗਰਮ ਕਰੇਗੀ।",
    "faq_q2": "ਮੈਂ ਪਲੇਟਫਾਰਮ ਰਾਹੀਂ ਕਿਹੜੇ ਦਸਤਾਵੇਜ਼ ਫਾਈਲ ਕਰ ਸਕਦਾ ਹਾਂ?",
    "faq_a2": "ਤੁਸੀਂ ਫਸਲ ਬੀਮਾ ਅਰਜ਼ੀਆਂ, ਸਬਸਿਡੀ ਫਾਰਮ, ਲੋਨ ਅਰਜ਼ੀਆਂ, ਜ਼ਮੀਨ ਦੇ ਰਿਕਾਰਡ, ਮਿੱਟੀ ਸਿਹਤ ਕਾਰਡ, ਅਤੇ ਪਾਲਣਾ ਸਰਟੀਫਿਕੇਟ ਸਮੇਤ ਸਾਰੇ ਪ੍ਰਮੁੱਖ ਖੇਤੀਬਾੜੀ ਦਸਤਾਵੇਜ਼ ਫਾਈਲ ਕਰ ਸਕਦੇ ਹੋ। ਸਾਡਾ ਸਿਸਟਮ 50+ ਤੋਂ ਵੱਧ ਦਸਤਾਵੇਜ਼ ਕਿਸਮਾਂ ਦਾ ਸਮਰਥਨ ਕਰਦਾ ਹੈ।",
    "faq_q3": "ਕੀ ਮੇਰਾ ਡੇਟਾ ਗੋਫਾਰਮਲੀਕਨੈਕਟ 'ਤੇ ਸੁਰੱਖਿਅਤ ਹੈ?",
    "faq_a3": "ਬਿਲਕੁਲ। ਅਸੀਂ ਬੈਂਕ-ਗ੍ਰੇਡ ਐਨਕ੍ਰਿਪਸ਼ਨ ਅਤੇ ਸਖਤ ਡੇਟਾ ਸੁਰੱਖਿਆ ਪ੍ਰੋਟੋਕੋਲ ਦੀ ਵਰਤੋਂ ਕਰਦੇ ਹਾਂ। ਤੁਹਾਡੀ ਜਾਣਕਾਰੀ ਸੁਰੱਖਿਅਤ ਢੰਗ ਨਾਲ ਸਟੋਰ ਕੀਤੀ ਜਾਂਦੀ ਹੈ ਅਤੇ ਤੁਹਾਡੀ ਸਹਿਮਤੀ ਬਿਨਾਂ ਤੀਜੀ ਧਿਰ ਨਾਲ ਸਾਂਝੀ ਨਹੀਂ ਕੀਤੀ ਜਾਂਦੀ। ਅਸੀਂ ਸਾਰੇ ਸਰਕਾਰੀ ਡੇਟਾ ਸੁਰੱਖਿਆ ਨਿਯਮਾਂ ਦੀ ਪਾਲਣਾ ਵੀ ਕਰਦੇ ਹਾਂ।",
    "faq_q4": "ਫਸਲ ਉਤਪਾਦਨ ਦੀਆਂ ਭਵਿੱਖਬਾਣੀਆਂ ਕਿੰਨੀਆਂ ਸਹੀ ਹਨ?",
    "faq_a4": "ਸਾਡੀਆਂ AI-ਸੰਚਾਲਿਤ ਭਵਿੱਖਬਾਣੀਆਂ ਦੀ ਸ਼ੁੱਧਤਾ ਦਰ 85-90% ਹੈ। ਅਸੀਂ ਸੈਟੇਲਾਈਟ ਚਿੱਤਰ, ਮੌਸਮ ਡੇਟਾ, ਮਿੱਟੀ ਦੀਆਂ ਸਥਿਤੀਆਂ, ਅਤੇ ਇਤਿਹਾਸਕ ਪੈਟਰਨਾਂ ਦੀ ਵਰਤੋਂ ਕਰਕੇ ਭਰੋਸੇਯੋਗ ਪੂਰਵ-ਅਨੁਮਾਨ ਪ੍ਰਦਾਨ ਕਰਦੇ ਹਾਂ। ਹਾਲਾਂਕਿ, ਭਵਿੱਖਬਾਣੀਆਂ ਨੂੰ ਤੁਹਾਡੀ ਖੇਤੀਬਾੜੀ ਮੁਹਾਰਤ ਦੇ ਨਾਲ ਮਾਰਗਦਰਸ਼ਨ ਵਜੋਂ ਵਰਤਿਆ ਜਾਣਾ ਚਾਹੀਦਾ ਹੈ।",
    "faq_q5": "ਕੀ ਮੈਂ ਗੋਫਾਰਮਲੀਕਨੈਕਟ ਨੂੰ ਆਫਲਾਈਨ ਐਕਸੈਸ ਕਰ ਸਕਦਾ ਹਾਂ?",
    "faq_a5": "ਹਾਂ, ਸਾਡੀ ਮੋਬਾਈਲ ਐਪ ਵਿੱਚ ਆਫਲਾਈਨ ਸਮਰੱਥਾਵਾਂ ਹਨ। ਤੁਸੀਂ ਇੰਟਰਨੈਟ ਤੋਂ ਬਿਨਾਂ ਆਪਣਾ ਡੇਟਾ ਦੇਖ ਸਕਦੇ ਹੋ, ਫਾਰਮ ਭਰ ਸਕਦੇ ਹੋ, ਅਤੇ ਟਿਊਟੋਰੀਅਲ ਐਕਸੈਸ ਕਰ ਸਕਦੇ ਹੋ। ਇੱਕ ਵਾਰ ਜਦੋਂ ਤੁਸੀਂ ਵਾਪਸ ਆਨਲਾਈਨ ਹੋਵੋ, ਸਾਰੀਆਂ ਤਬਦੀਲੀਆਂ ਸਵੈਚਲਿਤ ਤੌਰ 'ਤੇ ਕਲਾਉਡ ਨਾਲ ਸਿੰਕ ਹੋ ਜਾਂਦੀਆਂ ਹਨ।",
    "faq_q6": "ਕੀ ਖਰਚੇ ਸ਼ਾਮਲ ਹਨ?",
    "faq_a6": "ਮੁੱਢਲੀਆਂ ਵਿਸ਼ੇਸ਼ਤਾਵਾਂ ਸਾਰੇ ਕਿਸਾਨਾਂ ਲਈ ਪੂਰੀ ਤਰ੍ਹਾਂ ਮੁਫਤ ਹਨ। ਉੱਨਤ ਵਿਸ਼ਲੇਸ਼ਣ, ਪ੍ਰਾਇਰਿਟੀ ਸਹਾਇਤਾ, ਅਤੇ ਵਾਧੂ ਸਟੋਰੇਜ ਵਰਗੀਆਂ ਪ੍ਰੀਮੀਅਮ ਵਿਸ਼ੇਸ਼ਤਾਵਾਂ 99 ਰੁਪਏ/ਮਹੀਨੇ ਤੋਂ ਸ਼ੁਰੂ ਹੋਣ ਵਾਲੀਆਂ ਕਿਫਾਇਤੀ ਸਬਸਕ੍ਰਿਪਸ਼ਨ ਯੋਜਨਾਵਾਂ ਦੁਆਰਾ ਉਪਲਬਧ ਹਨ।",
    "faq_q7": "ਮੈਂ ਤਕਨੀਕੀ ਸਹਾਇਤਾ ਕਿਵੇਂ ਪ੍ਰਾਪਤ ਕਰਾਂ?",
    "faq_a7": "ਅਸੀਂ ਕਈ ਚੈਨਲਾਂ - ਫੋਨ (1800-3010-1000), ਈਮੇਲ, ਲਾਈਵ ਚੈਟ, ਅਤੇ ਵਟਸਐਪ ਰਾਹੀਂ 24/7 ਸਹਾਇਤਾ ਪ੍ਰਦਾਨ ਕਰਦੇ ਹਾਂ। ਸਾਡੇ ਖੇਤੀਬਾੜੀ ਮਾਹਰ ਕਿਸੇ ਵੀ ਤਕਨੀਕੀ ਜਾਂ ਖੇਤੀਬਾੜੀ-ਸੰਬੰਧੀ ਸਵਾਲਾਂ ਵਿੱਚ ਤੁਹਾਡੀ ਮਦਦ ਲਈ ਹਮੇਸ਼ਾ ਤਿਆਰ ਹਨ।",
    "faq_q8": "ਕੀ ਮੈਂ ਗੋਫਾਰਮਲੀਕਨੈਕਟ ਨੂੰ ਹੋਰ ਖੇਤੀਬਾੜੀ ਸੰਦਾਂ ਨਾਲ ਏਕੀਕ੍ਰਿਤ ਕਰ ਸਕਦਾ ਹਾਂ?",
    "faq_a8": "ਹਾਂ, ਗੋਫਾਰਮਲੀਕਨੈਕਟ ਪ੍ਰਸਿੱਧ ਖੇਤੀਬਾੜੀ ਉਪਕਰਣਾਂ, ਮੌਸਮ ਸਟੇਸ਼ਨਾਂ, ਅਤੇ ਵਿੱਤੀ ਸੇਵਾਵਾਂ ਨਾਲ ਏਕੀਕ੍ਰਿਤ ਹੁੰਦਾ ਹੈ। ਸਾਡੇ ਕੋਲ ਕਸਟਮ ਏਕੀਕਰਣ ਅਤੇ ਪ੍ਰਮੁੱਖ ਖੇਤੀਬਾੜੀ ਤਕਨਾਲੋਜੀ ਪ੍ਰਦਾਤਾਵਾਂ ਨਾਲ ਸਾਂਝੇਦਾਰੀ ਲਈ APIs ਉਪਲਬਧ ਹਨ।",
    
