    "iec_description_1": "ਆਈਈਸੀ (ਆਯਾਤ ਨਿਰਯਾਤ ਕੋਡ) ਡੀਜੀਐਫਟੀ ਦੁਆਰਾ ਜਾਰੀ ਕੀਤਾ ਗਿਆ 10-ਅੰਕਾਂ ਦਾ ਅਲਫਾਨਿਊਮਰਿਕ ਕੋਡ ਹੈ।",
    "iec_description_2": "ਇਹ ਭਾਰਤ ਵਿੱਚ ਆਯਾਤ ਜਾਂ ਨਿਰਯਾਤ ਕਾਰੋਬਾਰ ਵਿੱਚ ਸ਼ਾਮਲ ਵਿਅਕਤੀਆਂ/ਸੰਸਥਾਵਾਂ ਲਈ ਲਾਜ਼ਮੀ ਹੈ।",
    "iec_description_3": "ਕਸਟਮਜ਼ ਕਲੀਅਰੈਂਸ, ਵਿਦੇਸ਼ੀ ਮੁਦਰਾ ਲੈਣ-ਦੇਣ, ਅਤੇ ਅੰਤਰਰਾਸ਼ਟਰੀ ਵਪਾਰ ਲਈ ਲੋੜੀਂਦਾ।",
    "iec_description_4": "ਜੀਵਨ ਭਰ ਲਈ ਵੈਧ, ਕੋਈ ਨਵੀਨੀਕਰਨ ਦੀ ਲੋੜ ਨਹੀਂ।",
    "benefits_of_iec_registration": "ਆਈਈਸੀ ਰਜਿਸਟ੍ਰੇਸ਼ਨ ਦੇ ਲਾਭ:",
