  "what_is_icegate": "🌐 আইসিইগেট কী?",
  "icegate_definition_1": "• ইন্ডিয়ান কাস্টমস ইলেকট্রনিক গেটওয়ে হল বাণিজ্য এবং কাস্টমস ক্লিয়ারেন্সের জন্য একটি পোর্টাল",
  "icegate_definition_2": "• বিভিন্ন কাস্টমস নথির জন্য ই-ফাইলিং পরিষেবা প্রদান করে (যেমন, বিল অফ এন্ট্রি, শিপিং বিল)",
  "icegate_definition_3": "• কাস্টমস শুল্ক এবং অন্যান্য চার্জের অনলাইন পেমেন্ট সুবিধা দেয়",
  "icegate_definition_4": "• ভারতীয় কাস্টমসের সাথে মিথস্ক্রিয়ার জন্য আমদানিকারক এবং রপ্তানিকারকদের জন্য অপরিহার্য",
