  "icegate_benefit_2": "• আমদানি ও রপ্তানি চালানের দ্রুত প্রক্রিয়াকরণ",
  "icegate_benefit_3": "• কাস্টমস ডেটা এবং স্ট্যাটাস আপডেটের অনলাইন অ্যাক্সেস",
  "icegate_benefit_4": "• কাগজপত্র এবং ম্যানুয়াল হস্তক্ষেপ হ্রাস",
