// FAQ Questions and Answers
faq_q1: "मी माझे शेत गोफार्मलीकनेक्टवर कसे नोंदवू?",
faq_a1:
  "नोंदणी सोपी आणि विनामूल्य आहे. 'सुरू करा' वर क्लिक करा, तुमचे मूलभूत शेत तपशील भरा, आवश्यक कागदपत्रे अपलोड करा आणि तुमचा मोबाइल नंबर सत्यापित करा. आमची टीम २४ तासांत तुमचे खाते पुनरावलोकन करेल आणि सक्रिय करेल.",
faq_q2: "मी प्लॅटफॉर्मद्वारे कोणती कागदपत्रे दाखल करू शकतो?",
faq_a2:
  "तुम्ही पीक विमा अर्ज, अनुदान फॉर्म, कर्ज अर्ज, जमीन नोंदी, माती आरोग्य कार्डे आणि अनुपालन प्रमाणपत्रांसह सर्व प्रमुख शेती कागदपत्रे दाखल करू शकता. आमची प्रणाली ५०+ कागदपत्र प्रकारांना समर्थन देते.",
faq_q3: "गोफार्मलीकनेक्टवर माझा डेटा सुरक्षित आहे का?",
faq_a3:
  "नक्कीच. आम्ही बँक-स्तरीय एन्क्रिप्शन वापरतो आणि कठोर डेटा संरक्षण प्रोटोकॉलचे पालन करतो. तुमची माहिती सुरक्षितपणे संग्रहित केली जाते आणि तुमच्या संमतीशिवाय तृतीय पक्षांसह सामायिक केली जात नाही. आम्ही सर्व सरकारी डेटा संरक्षण नियमांचे पालन करतो.",
faq_q4: "पीक उत्पन्न अंदाज किती अचूक आहेत?",
faq_a4:
  "आमच्या AI-आधारित अंदाजांचा अचूकता दर ८५-९०% आहे. आम्ही उपग्रह प्रतिमा, हवामान डेटा, मातीच्या परिस्थिती आणि ऐतिहासिक नमुन्यांचा उपयोग विश्वासार्ह अंदाज प्रदान करण्यासाठी करतो. तथापि, अंदाज तुमच्या शेती तज्ञतेसह मार्गदर्शन म्हणून वापरले पाहिजेत.",
faq_q5: "मी गोफार्मलीकनेक्ट ऑफलाइन वापरू शकतो का?",
faq_a5:
  "होय, आमच्या मोबाइल ॲपमध्ये ऑफलाइन क्षमता आहेत. तुम्ही तुमचा डेटा पाहू शकता, फॉर्म भरा आणि इंटरनेटशिवाय ट्यूटोरियल्स पाहू शकता. एकदा तुम्ही पुन्हा ऑनलाइन आलात की, सर्व बदल स्वयंचलितपणे क्लाउडवर समन्वयित होतात.",
faq_q6: "खर्च किती आहे?",
faq_a6:
  "मूलभूत वैशिष्ट्ये सर्व शेतकऱ्यांसाठी पूर्णपणे विनामूल्य आहेत. प्रगत विश्लेषणे, प्राधान्य समर्थन आणि अतिरिक्त स्टोरेज यासारख्या प्रीमियम वैशिष्ट्ये ₹९९/महिना पासून सुरू होणाऱ्या परवडणाऱ्या सबस्क्रिप्शन योजनांद्वारे उपलब्ध आहेत.",
faq_q7: "तांत्रिक समर्थन कसे मिळवावे?",
faq_a7:
  "आम्ही फोन (१८००-३०१०-१०००), ईमेल, लाइव्ह चॅट आणि व्हॉट्सअॅपद्वारे २४/७ समर्थन ऑफर करतो. आमचे शेती तज्ञ कोणत्याही तांत्रिक किंवा शेती-संबंधित प्रश्नांसाठी तुम्हाला मदत करण्यासाठी नेहमी तयार असतात.",
faq_q8: "मी गोफार्मलीकनेक्ट इतर शेती साधनांसह एकत्रित करू शकतो का?",
faq_a8:
  "होय, गोफार्मलीकनेक्ट लोकप्रिय शेती उपकरणे, हवामान स्टेशन आणि वित्तीय सेवांसह एकत्रित होते. आमच्याकडे सानुकूल एकीकरणासाठी API उपलब्ध आहेत आणि प्रमुख शेती तंत्रज्ञान प्रदात्यांसह भागीदारी आहे.",

