faq_q1: "கோஃபார்ம்லி இணைப்பில் எனது பண்ணையை எவ்வாறு பதிவு செய்வது?",
faq_a1: "பதிவு எளிதானது மற்றும் இலவசம். 'தொடங்கவும்' என்பதைக் கிளிக் செய்யவும், உங்கள் அடிப்படை பண்ணை விவரங்களை நிரப்பவும், தேவையான ஆவணங்களை பதிவேற்றவும், உங்கள் மொபைல் எண்ணை சரிபார்க்கவும். எங்கள் குழு 24 மணி நேரத்திற்குள் உங்கள் கணக்கை மதிப்பாய்வு செய்து செயல்படுத்தும்.",
faq_q2: "இந்த தளத்தில் எந்த ஆவணங்களை தாக்கல் செய்யலாம்?",
faq_a2: "பயிர் காப்பீடு விண்ணப்பங்கள், மானிய படிவங்கள், கடன் விண்ணப்பங்கள், நில பதிவுகள், மண் ஆரோக்கிய அட்டைகள் மற்றும் இணக்க சான்றிதழ்கள் உட்பட அனைத்து முக்கிய விவசாய ஆவணங்களையும் தாக்கல் செய்யலாம். எங்கள் அமைப்பு 50+ ஆவண வகைகளை ஆதரிக்கிறது.",
faq_q3: "கோஃபார்ம்லி இணைப்பில் எனது தரவு பாதுகாப்பானதா?",
faq_a3: "நிச்சயமாக. நாங்கள் வங்கி-தர குறியாக்கத்தைப் பயன்படுத்துகிறோம் மற்றும் கடுமையான தரவு பாதுகாப்பு நெறிமுறைகளைப் பின்பற்றுகிறோம். உங்கள் தகவல் பாதுகாப்பாக சேமிக்கப்படுகிறது மற்றும் உங்கள் அனுமதியின்றி மூன்றாம் தரப்பினருடன் பகிரப்படுவதில்லை. நாங்கள் அனைத்து அரசு தரவு பாதுகாப்பு ஒழுங்குமுறைகளுடனும் இணக்கமாக இருக்கிறோம்.",
faq_q4: "பயிர் விளைச்சல் கணிப்புகள் எவ்வளவு துல்லியமானவை?",
faq_a4: "எங்கள் AI-ஆதரவு கணிப்புகள் 85-90% துல்லிய விகிதத்தைக் கொண்டுள்ளன. நாங்கள் செயற்கைக்கோள் படங்கள், வானிலை தரவு, மண் நிலைமைகள் மற்றும் வரலாற்று முறைகளைப் பயன்படுத்தி நம்பகமான முன்கணிப்புகளை வழங்குகிறோம். இருப்பினும், உங்கள் விவசாய நிபுணத்துவத்துடன் கணிப்புகளை வழிகாட்டுதலாகப் பயன்படுத்த வேண்டும்.",
faq_q5: "கோஃபார்ம்லி இணைப்பை ஆஃப்லைனில் அணுக முடியுமா?",
faq_a5: "ஆம், எங்கள் மொபைல் ஆப் ஆஃப்லைன் திறன்களைக் கொண்டுள்ளது. இணையம் இல்லாமல் உங்கள் தரவைப் பார்க்கலாம், படிவங்களை நிரப்பலாம் மற்றும் பயிற்சிகளை அணுகலாம். மீண்டும் ஆன்லைனில் வந்தவுடன், அனைத்து மாற்றங்களும் கிளவுட்டுடன் தானாக ஒத்திசைக்கப்படும்.",
faq_q6: "என்ன செலவுகள் உள்ளன?",
faq_a6: "அனைத்து விவசாயிகளுக்கும் அடிப்படை அம்சங்கள் முற்றிலும் இலவசம். மேம்பட்ட பகுப்பாய்வு, முன்னுரிமை ஆதரவு மற்றும் கூடுதல் சேமிப்பு போன்ற பிரீமியம் அம்சங்கள் ₹99/மாதம் முதல் மலிவு விலையில் சந்தா திட்டங்கள் மூலம் கிடைக்கின்றன.",
faq_q7: "தொழில்நுட்ப ஆதரவை எவ்வாறு பெறுவது?",
faq_a7: "நாங்கள் தொலைபேசி (1800-3010-1000), மின்னஞ்சல், நேரடி அரட்டை மற்றும் வாட்ஸ்அப் மூலம் 24/7 ஆதரவை வழங்குகிறோம். எங்கள் விவசாய நிபுணர்கள் எந்தவொரு தொழில்நுட்ப அல்லது விவசாயம் தொடர்பான கேள்விகளுக்கு உங்களுக்கு உதவ தயாராக உள்ளனர்.",
faq_q8: "கோஃபார்ம்லி இணைப்பை மற்ற விவசாய கருவிகளுடன் ஒருங்கிணைக்க முடியுமா?",
faq_a8: "ஆம், கோஃபார்ம்லி இணைப்பு பிரபலமான விவசாய உபகரணங்கள், வானிலை நிலையங்கள் மற்றும் நிதி சேவைகளுடன் ஒருங்கிணைக்கிறது. தனிப்பயன் ஒருங்கிணைப்புகளுக்காக APIகள் மற்றும் முக்கிய விவசாய தொழில்நுட்ப வழங்குநர்களுடன் கூட்டாண்மைகள் உள்ளன.",

