adcode_definition_3: "• இறக்குமதி/ஏற்றுமதி பரிவர்த்தனைகள் மற்றும் அந்நிய பணப்பரிமாற்றங்களுக்கு தேவை",
adcode_definition_4: "• FOREX இணக்கத்திற்காக உங்கள் வணிகத்தை வங்கியுடன் இணைக்கிறது",
adcode_definition_5: "• சுங்க அனுமதி மற்றும் RBI அறிக்கையிடலுக்கு அவசியம்",
