    what_is_iec: "IEC అంటే ఏమిటి?",
    iec_description_1: "IEC (దిగుమతి ఎగుమతి కోడ్) అనేది DGFT ద్వారా జారీ చేయబడిన 10-అంకెల ఆల్ఫాన్యూమరిక్ కోడ్.",
    iec_description_2: "ఇది భారతదేశంలో దిగుమతి లేదా ఎగుమతి వ్యాపారంలో నిమగ్నమైన వ్యక్తులు/ఎంటిటీలకు తప్పనిసరి.",
    iec_description_3: "కస్టమ్స్ క్లియరెన్స్, విదేశీ మారక లావాదేవీలు, మరియు అంతర్జాతీయ వాణిజ్యం కోసం అవసరం.",
    iec_description_4: "జీవితకాలం చెల్లుబాటు అవుతుంది, పునరుద్ధరణ అవసరం లేదు.",
    benefits_of_iec_registration: "IEC రిజిస్ట్రేషన్ యొక్క ప్రయోజనాలు:",
    iec_benefit_1: "దిగుమతి మరియు ఎగుమతి కార్యకలాపాలను సాధ్యం చేస్తుంది.",
    iec_benefit_2: "DGFT నుండి ఎగుమతి ప్రోత్సాహకాలు మరియు స్కీమ్‌లకు యాక్సెస్.",
    iec_benefit_3: "కస్టమ్స్ ప్రక్రియలు మరియు డాక్యుమెంటేషన్‌ను సరళీకరిస్తుంది.",
    iec_benefit_4: "ప్రపంచ మార్కెట్లలో వ్యాపార విశ్వసనీయతను మెరుగుపరుస్తుంది.",
    iec_benefit_5: "సంవత్సరానికి నియమ నిబంధనలు లేదా ఫైలింగ్ అవసరాలు లేవు.",
    dsc_definition_1: "డిజిటల్ సిగ్నేచర్ సర్టిఫికెట్ అనేది సురక్షిత డిజిటల్ కీ",
