  "copyright_text": "© 2025 ગો ફાર્મલી કનેક્ટ - ટેકનોલોજી દ્વારા કૃષિમાં પરિવર્તન. બધા હકો અનામત.",
  "made_with_love": "ખેડૂતો માટે ❤️ સાથે બનાવેલ",
  "proudly_indian": "🇮🇳 ગર્વથી ભારતીય",
  "serving_farmers": "ભારતભરના ખેડૂતોની સેવા",
  "empowering_farmers": "આધુનિક કૃષિ માટે અદ્યતન ડિજિટલ ઉકેલો સાથે ખેડૂતોને સશક્ત બનાવવું. આજે જ કૃષિ ક્રાંતિમાં જોડાઓ.",
  "faq_q1": "હું ગો ફાર્મલી કનેક્ટ પર મારું ફાર્મ કેવી રીતે નોંધણી કરાવું?",
  "faq_a1": "નોંધણી સરળ અને મફત છે. 'શરૂઆત કરો' પર ક્લિક કરો, તમારી મૂળભૂત ફાર્મ વિગતો ભરો, જરૂરી દસ્તાવેજો અપલોડ કરો અને તમારો મોબાઇલ નંબર ચકાસો. અમારી ટીમ 24 કલાકની અંદર તમારું એકાઉન્ટ સમીક્ષા કરશે અને સક્રિય કરશે.",
  "faq_q2": "હું પ્લેટફોર્મ દ્વારા કયા દસ્તાવેજો ફાઇલ કરી શકું?",
  "faq_a2": "તમે પાક વીમો અરજીઓ, સબસિડી ફોર્મ્સ, લોન અરજીઓ, જમીન રેકોર્ડ્સ, માટી આરોગ્ય કાર્ડ્સ અને પાલન પ્રમાણપત્રો સહિત તમામ મુખ્ય કૃષિ દસ્તાવેજો ફાઇલ કરી શકો છો. અમારી સિસ્ટમ 50+ થી વધુ દસ્તાવેજ પ્રકારોને સપોર્ટ કરે છે.",
  "faq_q3": "શું મારો ડેટા ગો ફાર્મલી કનેક્ટ પર સુરક્ષિત છે?",
  "faq_a3": "નિશ્ચિતપણે. અમે બેંક-ગ્રેડ એન્ક્રિપ્શનનો ઉપયોગ કરીએ છીએ અને કડક ડેટા સુરક્ષા પ્રોટોકોલ્સનું પાલન કરીએ છીએ. તમારી માહિતી સુરક્ષિત રીતે સંગ્રહિત થાય છે અને તમારી સંમતિ વિના તૃતીય પક્ષો સાથે ક્યારેય શેર થતી નથી. અમે તમામ સરકારી ડેટા સુરક્ષા નિયમોનું પણ પાલન કરીએ છીએ.",
  "faq_q4": "પાક ઉપજ આગાહીઓ કેટલી સચોટ છે?",
  "faq_a4": "અમારી AI-સંચાલિત આગાહીઓ 85-90% ની ચોકસાઈ દર ધરાવે છે. અમે ઉપગ્રહ ચિત્રો, હવામાન ડેટા, માટીની સ્થિતિ અને ઐતિહાસિક પેટર્નનો ઉપયોગ કરીને વિશ્વસનીય આગાહીઓ પૂરી પાડીએ છીએ. જો કે, આગાહીઓ તમારી ખેતીની નિપુણતા સાથે માર્ગદર્શન તરીકે ઉપયોગમાં લેવી જોઈએ.",
  "faq_q5": "શું હું ગો ફાર્મલી કનેક્ટ ઑફલાઇન ઍક્સેસ કરી શકું?",
  "faq_a5": "હા, અમારી મોબાઇલ એપમાં ઑફલાઇન ક્ષમતાઓ છે. તમે ઇન્ટરનેટ વિના તમારો ડેટા જોઈ શકો છો, ફોર્મ્સ ભરી શકો છો અને ટ્યુટોરિયલ્સ ઍક્સેસ કરી શકો છો. એકવાર તમે ફરીથી ઑનલાઇન થશો, તમામ ફેરફારો આપોઆપ ક્લાઉડ સાથે સિંક થઈ જશે.",
  "faq_q6": "ખર્ચ શું છે?",
  "faq_a6": "બધા ખેડૂતો માટે મૂળભૂત સુવિધાઓ સંપૂર્ણપણે મફત છે. અદ્યતન વિશ્લેષણ, પ્રાથમિકતા સપોર્ટ અને વધારાના સ્ટોરેજ જેવી પ્રીમિયમ સુવિધાઓ ₹99/મહિનાથી શરૂ થતી પરવડે તેવી સબ્સ્ક્રિપ્શન યોજનાઓ દ્વારા ઉપલબ્ધ છે.",
  "faq_q7": "હું ટેકનિકલ સપોર્ટ કેવી રીતે મેળવી શકું?",
  "faq_a7": "અમે બહુવિધ ચેનલો દ્વારા 24/7 સપોર્ટ પૂરો પાડીએ છીએ - ફોન (1800-3010-1000), ઇમેઇલ, લાઇવ ચેટ અને વોટ્સએપ. અમારા કૃષિ નિષ્ણાતો કોઈપણ ટેકનિકલ અથવા ખેતી સંબંધિત પ્રશ્નોમાં તમને મદદ કરવા હંમેશા તૈયાર છે.",
  "faq_q8": "શું હું ગો ફાર્મલી કનેક્ટને અન્ય ખેતી સાધનો સાથે એકીਕૃત કરી શકું?",
  "faq_a8": "હા, ગો ફાર્મલી કનેક્ટ લોકપ્રિય ખેતી સાધનો, હવામાન સ્ટેશનો અને નાણાકીય સેવાઓ સાથે એકીકૃત થાય છે. અમારી પાસે કસ્ટમ એકીકરણ અને મુખ્ય કૃષિ ટેકનોલોજી પ્રદાતાઓ સાથે ભાગીદારી માટે APIs ઉપલબ્ધ છે.",
