  "iec_description_1": "આઈઈસી (આયાત નિકાસ કોડ) એ ડીજીએફટી દ્વારા જારી કરાયેલ 10-અંકનો આલ્ફાન્યૂમેરિક કોડ છે.",
  "iec_description_2": "ભારતમાં આયાત અથવા નિકાસ વ્યવસાયમાં રોકાયેલ વ્યક્તિઓ/એન્ટિટીઓ માટે તે ફરજિયાત છે.",
  "iec_description_3": "કસ્ટમ્સ ક્લિયરન્સ, વિદેશી વિનિમય વ્યવહારો અને આંતરરાષ્ટ્રીય વેપાર માટે જરૂરી.",
  "iec_description_4": "જીવનભર માટે માન્ય, નવીકરણની જરૂર નથી.",
  "benefits_of_iec_registration": "આઈઈસી નોંધણીના ફાયદા:",
  "iec_benefit_1": "આંતરરાષ્ટ્રીય વેપાર કામગીરી (આયાત અને નિકાસ) ને સક્ષમ કરે છે.",
  "iec_benefit_2": "ડીજીએફટી તરફથી નિકાસ પ્રોત્સાહનો અને યોજનાઓની ઍક્સેસ.",
  "iec_benefit_3": "કસ્ટમ્સ પ્રક્રિયાઓ અને દસ્તાવેજીકરણને સરળ બનાવે છે.",
  "iec_benefit_4": "વૈશ્વિક બજારોમાં વ્યવસાયની વિશ્વસનીયતા વધારે છે.",
  "iec_benefit_5": "કોઈ વાર્ષિક પાલન અથવા ફાઇલિંગ આવશ્યકતાઓ નથી.",
  "dsc_definition_1": "ડિજિટલ સિગ્નેચર સર્ટિફિકેટ એ એક સુરક્ષિત ડિજિટલ કી છે",
  "dsc_definition_2": "ડિજિટલ વ્યવહારોમાં તમારી ઓળખને પ્રમાણિત કરવા માટે વપરાય છે",
  "dsc_definition_3": "વિવિધ સરકારી ફોર્મ્સ અને દસ્તાવેજો ફાઇલ કરવા માટે જરૂરી",
  "dsc_definition_4": "ઇલેક્ટ્રોનિક દસ્તાવેજોને કાયદેસર માન્યતા આપે છે",
  "dsc_definition_5": "જીએસટી રિટર્ન્સ, આવકવેરા ફાઇલિંગ્સ અને વધુ માટે આવશ્યક",
  "uses_of_dsc": "ડીએસસીનો ઉપયોગ:",
  "dsc_use_1": "જીએસટી રિટર્ન્સ અને અન્ય કર દસ્તાવેજો ફાઇલ કરવા",
  "dsc_use_2": "ઇ-ટેન્ડરિંગ અને સરકારી ખરીદી",
  "dsc_use_3": "કંપની નોંધણી અને પાલન ફાઇલિંગ્સ",
  "dsc_use_4": "બેન્કિંગ અને નાણાકીય વ્યવહારો",
  "dsc_use_5": "કાયદેસર દસ્તાવેજ પ્રમાણીકરણ",
  "important_notes": "મહત્વની નોંધો:",
  "dsc_note_1": "ડીએસસી સામાન્ય રીતે જારી થયાની તારીખથી 1-3 વર્ષ માટે માન્ય છે",
  "dsc_note_2": "તમને યુએસબી ટોકન પર અથવા સોફ્ટવેર સર્ટિફિકેટ તરીકે ડીએસસી મળશે",
  "dsc_note_3": "તમારા ડીએસસી પાસવર્ડને સુરક્ષિત અને ગોપનીય રાખો",
  "dsc_note_4": "સતત ઉપયોગ માટે સમાપ્તિ પહેલાં નવીકરણ જરૂરી છે",
  "dsc_application_submitted_processing": "તમારી ડીએસસી નોંધણી અરજી સબમિટ થઈ છે અને હાલમાં પ્રોસેસ થઈ રહી છે. તમે પ્રગતિ વિભાગમાં પ્રગતિ ટ્રેક કરી શકો છો.",
  "submit_dsc_application": "ડીએસસી અરજી સબમિટ કરો ({{progress}}% પૂર્ણ)",
  "file_size_is": "ફાઇલનું કદ છે",
  "iec_certificate": "આઈઈસી પ્રમાણપત્ર",
  "from_iec_registration": "આઈઈસી નોંધણીમાંથી",
  "what_is_icegate": "🌐 આઈસીઈગેટ શું છે?",
  "icegate_definition_1": "• ભારતીય કસ્ટમ્સ ઇલેક્ટ્રોનિક ગેટવે એ વેપાર અને કસ્ટમ્સ ક્લિયરન્સ માટેનું પોર્ટલ છે",
  "icegate_definition_2": "• વિવિધ કસ્ટમ્સ દસ્તાવેજો (દા.ત., બિલ ઓફ એન્ટ્રી, શિપિંગ બિલ) માટે ઇ-ફાઇલિંગ સેવાઓ પૂરી પાડે છે",
  
  "icegate_definition_3": "• કસ્ટમ્સ ડ્યુટી અને અન્ય ચાર્જની ઓનલાઇન ચુકવણીની સુવિધા આપે છે",
  "icegate_definition_4": "• ભારતીય કસ્ટમ્સ સાથે ક્રિયાપ્રતિક્રિયા કરવા માટે આયાતકારો અને નિકાસકારો માટે આવશ્યક",
  "benefits_of_icegate": "📋 આઈસીઈગેટ નોંધણીના ફાયદા:",
  "icegate_benefit_1": "• સરળ કસ્ટમ્સ ક્લિયરન્સ પ્રક્રિયા",
  "icegate_benefit_2": "• આયાત અને નિકાસ શિપમેન્ટની ઝડપી પ્રક્રિયા",
  "icegate_benefit_3": "• કસ્ટમ્સ ડેટા અને સ્થિતિ અપડેટ્સની ઓનલાઇન ઍક્સેસ",
  "icegate_benefit_4": "• ઘટાડેલ કાગળનું કામ અને મેન્યુઅલ હસ્તક્ષેપ",
  "icegate_benefit_5": "• વેપાર કામગીરીમાં વધેલી પારદર્શિતા અને કાર્યક્ષમતા",
  "icegate_application_submitted_processing": "તમારી આઈસીઈગેટ નોંધણી અરજી સબમિટ થઈ છે અને હાલમાં પ્રોસેસ થઈ રહી છે. તમે પ્રગતિ વિભાગમાં પ્રગતિ ટ્રેક કરી શકો છો.",
