  "what_is_adcode": "💰 એડી કોડ શું છે?",
  "adcode_definition_1": "• ઓથોરાઇઝ્ડ ડીલર કોડ એ અનન્ય ઓળખ નંબર છે",
  "adcode_definition_2": "• વિદેશી વિનિમય વ્યવહારો માટે ઓથોરાઇઝ્ડ ડીલર બેંકો દ્વારા જારી કરવામાં આવે છે",
