  "faq_a1": "ਰਜਿਸਟ੍ਰੇਸ਼ਨ ਸਧਾਰਨ ਅਤੇ ਮੁਫਤ ਹੈ। 'ਸ਼ੁਰੂ ਕਰੋ' 'ਤੇ ਕਲਿੱਕ ਕਰੋ, ਆਪਣੇ ਮੁਢਲੇ ਖੇਤ ਵੇਰਵੇ ਭਰੋ, ਲੋੜੀਂਦੇ ਦਸਤਾਵੇਜ਼ ਅਪਲੋਡ ਕਰੋ, ਅਤੇ ਆਪਣਾ ਮੋਬਾਈਲ ਨੰਬਰ ਪ੍ਰਮਾਣਿਤ ਕਰੋ। ਸਾਡੀ ਟੀਮ 24 ਘੰਟਿਆਂ ਦੇ ਅੰਦਰ ਤੁਹਾਡੇ ਖਾਤੇ ਦੀ ਸਮੀਖਿਆ ਅਤੇ ਸਰਗਰਮ ਕਰੇਗੀ।",
  "faq_q2": "ਮੈਂ ਪਲੇਟਫਾਰਮ ਰਾਹੀਂ ਕਿਹੜੇ ਦਸਤਾਵੇਜ਼ ਫਾਈਲ ਕਰ ਸਕਦਾ ਹਾਂ?",
  "faq_a2": "ਤੁਸੀਂ ਸਾਰੇ ਪ੍ਰਮੁੱਖ ਖੇਤੀਬਾੜੀ ਦਸਤਾਵੇਜ਼ ਜਿਵੇਂ ਕਿ ਫਸਲ ਬੀਮਾ ਅਰਜ਼ੀਆਂ, ਸਬਸਿਡੀ ਫਾਰਮ, ਲੋਨ ਅਰਜ਼ੀਆਂ, ਜ਼ਮੀਨੀ ਰਿਕਾਰਡ, ਮਿੱਟੀ ਸਿਹਤ ਕਾਰਡ, ਅਤੇ ਪਾਲਣਾ ਸਰਟੀਫਿਕੇਟ ਫਾਈਲ ਕਰ ਸਕਦੇ ਹੋ। ਸਾਡਾ ਸਿਸਟਮ 50+ ਤੋਂ ਵੱਧ ਦਸਤਾਵੇਜ਼ ਕਿਸਮਾਂ ਨੂੰ ਸਮਰਥਨ ਦਿੰਦਾ ਹੈ।",
  "faq_q3": "ਕੀ ਮੇਰਾ ਡਾਟਾ ਗੋਫਾਰਮਲੀਕਨੈਕਟ 'ਤੇ ਸੁਰੱਖਿਅਤ ਹੈ?",
  "faq_a3": "ਬਿਲਕੁਲ। ਅਸੀਂ ਬੈਂਕ-ਗ੍ਰੇਡ ਐਨਕ੍ਰਿਪਸ਼ਨ ਅਤੇ ਸਖਤ ਡਾਟਾ ਸੁਰੱਖਿਆ ਪ੍ਰੋਟੋਕੋਲ ਦੀ ਪਾਲਣਾ ਕਰਦੇ ਹਾਂ। ਤੁਹਾਡੀ ਜਾਣਕਾਰੀ ਸੁਰੱਖਿਅਤ ਢੰਗ ਨਾਲ ਸਟੋਰ ਕੀਤੀ ਜਾਂਦੀ ਹੈ ਅਤੇ ਤੁਹਾਡੀ ਸਹਿਮਤੀ ਤੋਂ ਬਿਨਾਂ ਕਦੇ ਵੀ ਤੀਜੀ ਧਿਰ ਨਾਲ ਸਾਂਝੀ ਨਹੀਂ ਕੀਤੀ ਜਾਂਦੀ। ਅਸੀਂ ਸਾਰੇ ਸਰਕਾਰੀ ਡਾਟਾ ਸੁਰੱਖਿਆ ਨਿਯਮਾਂ ਦੀ ਪਾਲਣਾ ਵੀ ਕਰਦੇ ਹਾਂ।",
  "faq_q4": "ਫਸਲ ਉਤਪਾਦਨ ਭਵਿੱਖਬਾਣੀਆਂ ਕਿੰਨੀਆਂ ਸਟੀਕ ਹਨ?",
  "faq_a4": "ਸਾਡੀਆਂ AI-ਸੰਚਾਲਿਤ ਭਵਿੱਖਬਾਣੀਆਂ ਦੀ ਸਟੀਕਤਾ ਦਰ 85-90% ਹੈ। ਅਸੀਂ ਸੈਟੇਲਾਈਟ ਚਿੱਤਰਾਂ, ਮੌਸਮ ਡਾਟਾ, ਮਿੱਟੀ ਦੀਆਂ ਸਥਿਤੀਆਂ, ਅਤੇ ਇਤਿਹਾਸਕ ਪੈਟਰਨਾਂ ਦੀ ਵਰਤੋਂ ਕਰਕੇ ਭਰੋਸੇਯੋਗ ਪੂਰਵ-ਅਨੁਮਾਨ ਪ੍ਰਦਾਨ ਕਰਦੇ ਹਾਂ। ਹਾਲਾਂਕਿ, ਭਵਿੱਖਬਾਣੀਆਂ ਨੂੰ ਤੁਹਾਡੀ ਖੇਤੀਬਾੜੀ ਮੁਹਾਰਤ ਦੇ ਨਾਲ ਮਾਰਗਦਰਸ਼ਨ ਵਜੋਂ ਵਰਤਿਆ ਜਾਣਾ ਚਾਹੀਦਾ ਹੈ।",
  "faq_q5": "ਕੀ ਮੈਂ ਗੋਫਾਰਮਲੀਕਨੈਕਟ ਨੂੰ ਔਫਲਾਈਨ ਐਕਸੈਸ ਕਰ ਸਕਦਾ ਹਾਂ?",
  "faq_a5": "ਹਾਂ, ਸਾਡੀ ਮੋਬਾਈਲ ਐਪ ਵਿੱਚ ਔਫਲਾਈਨ ਸਮਰੱਥਾਵਾਂ ਹਨ। ਤੁਸੀਂ ਬਿਨਾਂ ਇੰਟਰਨੈਟ ਦੇ ਆਪਣਾ ਡਾਟਾ ਵੇਖ ਸਕਦੇ ਹੋ, ਫਾਰਮ ਭਰ ਸਕਦੇ ਹੋ, ਅਤੇ ਟਿਊਟੋਰੀਅਲ ਐਕਸੈਸ ਕਰ ਸਕਦੇ ਹੋ। ਇੱਕ ਵਾਰ ਜਦੋਂ ਤੁਸੀਂ ਵਾਪਸ ਔਨਲਾਈਨ ਹੁੰਦੇ ਹੋ, ਸਾਰੀਆਂ ਤਬਦੀਲੀਆਂ ਸਵੈਚਲਿਤ ਤੌਰ 'ਤੇ ਕਲਾਉਡ ਨਾਲ ਸਿੰਕ ਹੋ ਜਾਂਦੀਆਂ ਹਨ।",
  "faq_q6": "ਸ਼ਾਮਲ ਖਰਚੇ ਕੀ ਹਨ?",
  "faq_a6": "ਮੁਢਲੀਆਂ ਵਿਸ਼ੇਸ਼ਤਾਵਾਂ ਸਾਰੇ ਕਿਸਾਨਾਂ ਲਈ ਪੂਰੀ ਤਰ੍ਹਾਂ ਮੁਫਤ ਹਨ। ਉੱਨਤ ਵਿਸ਼ਲੇਸ਼ਣ, ਪ੍ਰਾਈਓਰਿਟੀ ਸਹਾਇਤਾ, ਅਤੇ ਵਾਧੂ ਸਟੋਰੇਜ ਵਰਗੀਆਂ ਪ੍ਰੀਮੀਅਮ ਵਿਸ਼ੇਸ਼ਤਾਵਾਂ ₹99/ਮਹੀਨਾ ਤੋਂ ਸ਼ੁਰੂ ਹੋਣ ਵਾਲੀਆਂ ਕਿਫਾਇਤੀ ਸਬਸਕ੍ਰਿਪਸ਼ਨ ਯੋਜਨਾਵਾਂ ਰਾਹੀਂ ਉਪਲਬਧ ਹਨ।",
  "faq_q7": "ਮੈਂ ਤਕਨੀਕੀ ਸਹਾਇਤਾ ਕਿਵੇਂ ਪ੍ਰਾਪਤ ਕਰਾਂ?",
  "faq_a7": "ਅਸੀਂ ਫੋਨ (1800-3010-1000), ਈਮੇਲ, ਲਾਈਵ ਚੈਟ, ਅਤੇ ਵਟਸਐਪ ਰਾਹੀਂ 24/7 ਸਹਾਇਤਾ ਪ੍ਰਦਾਨ ਕਰਦੇ ਹਾਂ। ਸਾਡੇ ਖੇਤੀਬਾੜੀ ਮਾਹਰ ਕਿਸੇ ਵੀ ਤਕਨੀਕੀ ਜਾਂ ਖੇਤੀਬਾੜੀ ਸੰਬੰਧੀ ਪੁੱਛਗਿੱਛ ਵਿੱਚ ਤੁਹਾਡੀ ਮਦਦ ਲਈ ਹਮੇਸ਼ਾ ਤਿਆਰ ਹਨ।",
  "faq_q8": "ਕੀ ਮੈਂ ਗੋਫਾਰਮਲੀਕਨੈਕਟ ਨੂੰ ਹੋਰ ਖੇਤੀ ਸੰਦਾਂ ਨਾਲ ਜੋੜ ਸਕਦਾ ਹਾਂ?",
  "faq_a8": "ਹਾਂ, ਗੋਫਾਰਮਲੀਕਨੈਕਟ ਪ੍ਰਸਿੱਧ ਖੇਤੀ ਸਾਜ਼ੋ-ਸਾਮਾਨ, ਮੌਸਮ ਸਟੇਸ਼ਨਾਂ, ਅਤੇ ਵਿੱਤੀ ਸੇਵਾਵਾਂ ਨਾਲ ਜੁੜਦਾ ਹੈ। ਸਾਡੇ ਕੋਲ ਕਸਟਮ ਏਕੀਕਰਣ ਅਤੇ ਪ੍ਰਮੁੱਖ ਖੇਤੀਬਾੜੀ ਤਕਨੀਕ ਪ੍ਰਦਾਤਾਵਾਂ ਨਾਲ ਸਾਂਝੇਦਾਰੀਆਂ ਲਈ APIs ਉਪਲਬਧ ਹਨ।",
