  "iec_benefit_2": "ਡੀਜੀਐਫਟੀ ਤੋਂ ਨਿਰਯਾਤ ਪ੍ਰੋਤਸਾਹਨ ਅਤੇ ਸਕੀਮਾਂ ਤੱਕ ਪਹੁੰਚ।",
  "iec_benefit_3": "ਕਸਟਮਜ਼ ਪ੍ਰਕਿਰਿਆਵਾਂ ਅਤੇ ਦਸਤਾਵੇਜ਼ੀਕਰਨ ਨੂੰ ਸਰਲ ਬਣਾਉਂਦਾ ਹੈ।",
  "iec_benefit_4": "ਗਲੋਬਲ ਬਾਜ਼ਾਰਾਂ ਵਿੱਚ ਵਪਾਰਕ ਵਿਸ਼ਵਸਨੀਯਤਾ ਨੂੰ ਵਧਾਉਂਦਾ ਹੈ।",
  "iec_benefit_5": "ਕੋਈ ਸਾਲਾਨਾ ਪਾਲਣਾ ਜਾਂ ਫਾਈਲਿੰਗ ਲੋੜਾਂ ਨਹੀਂ।",
  "dsc_definition_1": "ਡਿਜੀਟਲ ਸਿਗਨੇਚਰ ਸਰਟੀਫਿਕੇਟ ਇੱਕ ਸੁਰੱਖਿਅਤ ਡਿਜੀਟਲ ਕੁੰਜੀ ਹੈ",
