  "dsc_definition_3": "ਵੱਖ-ਵੱਖ ਸਰਕਾਰੀ ਫਾਰਮ ਅਤੇ ਦਸਤਾਵੇਜ਼ ਫਾਈਲ ਕਰਨ ਲਈ ਲੋੜੀਂਦਾ",
  "dsc_definition_4": "ਇਲੈਕਟ੍ਰਾਨਿਕ ਦਸਤਾਵੇਜ਼ਾਂ ਨੂੰ ਕਾਨੂੰਨੀ ਵੈਧਤਾ ਪ੍ਰਦਾਨ ਕਰਦਾ ਹੈ",
  "dsc_definition_5": "ਜੀਐਸਟੀ ਰਿਟਰਨ, ਆਮਦਨ ਕਰ ਫਾਈਲਿੰਗ, ਅਤੇ ਹੋਰ ਲਈ ਜ਼ਰੂਰੀ",
  "uses_of_dsc": "ਡੀਐਸਸੀ ਦੀਆਂ ਵਰਤੋਂ:",
  "dsc_use_1": "ಜಿಎಸ್‌ಟಿ ರಿಟರ್ನ್‌ಗಳು ಮತ್ತು ಇತರ ತೆರಿಗೆ ದಾಖಲೆಗಳನ್ನು ಸಲ್ಲಿಸುವುದು",
