  "dsc_use_4": "ಬ್ಯಾಂಕಿಂಗ್ ಮತ್ತು ಆರ್ಥಿಕ ವಹಿವಾಟುಗಳು",
  "dsc_use_5": "ಕಾನೂನು ದಾಖಲೆಗಳ ಪ್ರಮಾಣೀಕರಣ",
  "important_notes": "ಪ್ರಮುಖ ಟಿಪ್ಪಣಿಗಳು:",
  "dsc_note_1": "ಡಿಎಸ್‌ಸಿ ಸಾಮಾನ್ಯವಾಗಿ ಜಾರಿಯಾದ ದಿನಾಂಕದಿಂದ 1-3 ವರ್ಷಗಳವರೆಗೆ ಮಾನ್ಯವಾಗಿರುತ್ತದೆ",
  "dsc_note_2": "ನೀವು ಡಿಎಸ್‌ಸಿಯನ್ನು ಯುಎಸ್‌ಬಿ ಟೋಕನ್‌ನಲ್ಲಿ ಅಥವಾ ಸಾಫ್ಟ್‌ವೇರ್ ಪ್ರಮಾಣಪತ್ರವಾಗಿ ಪಡೆಯುತ್ತೀರಿ",
  "dsc_note_3": "ನಿಮ್ಮ ಡಿಎಸ್‌ಸಿ ಪಾಸ್‌ವರ್ಡ್‌ನ್ನು ಸುರಕ್ಷಿತವಾಗಿ ಮತ್ತು ಗೌಪ್ಯವಾಗಿರಿಸಿ",
