  "dsc_application_submitted_processing": "ನಿಮ್ಮ ಡಿಎಸ್‌ಸಿ ನೋಂದಣಿ ಅರ್ಜಿಯನ್ನು ಸಲ್ಲಿಸಲಾಗಿದೆ ಮತ್ತು ಪ್ರಸ್ತುತ ಪ್ರಕ್ರಿಯೆಯಲ್ಲಿದೆ. ನೀವು ಪ್ರಗತಿಯನ್ನು ಪ್ರಗತಿ ವಿಭಾಗದಲ್ಲಿ ಟ್ರ್ಯಾಕ್ ಮಾಡಬಹುದು.",
