  "from_iec_registration": "ಐಇಸಿ ನೋಂದಣಿಯಿಂದ",
  "what_is_icegate": "🌐 ಐಸಿಇಗೇಟ್ ಎಂದರೇನು?",
  "icegate_definition_1": "• ಭಾರತೀಯ ಕಸ್ಟಮ್ಸ್ ಎಲೆಕ್ಟ್ರಾನಿಕ್ ಗೇಟ್‌ವೇ ಒಂದು ವ್ಯಾಪಾರ ಮತ್ತು ಕಸ್ಟಮ್ಸ್ ಕ್ಲಿಯರೆನ್ಸ್‌ಗಾಗಿ ಒಂದು ಪೋರ್ಟಲ್ ಆಗಿದೆ",
  "icegate_definition_2": "• ವಿವಿಧ ಕಸ್ಟಮ್ಸ್ ದಾಖಲೆಗಳಿಗೆ ಇ-ಫೈಲಿಂಗ್ ಸೇವೆಗಳನ್ನು ಒದಗಿಸುತ್ತದೆ (ಉದಾಹರಣೆಗೆ, ಎಂಟ್ರಿ ಬಿಲ್, ಶಿಪ್ಪಿಂಗ್ ಬಿಲ್)",
  "icegate_definition_3": "• ಕಸ್ಟಮ್ಸ್ ಶುಲ್ಕಗಳು ಮತ್ತು ಇತರ ಶುಲ್ಕಗಳ ಆನ್‌ಲೈನ್ ಪಾವತಿಯನ್ನು ಸುಗಮಗೊಳಿಸುತ್ತದೆ",
  "icegate_definition_4": "• ಭಾರತೀಯ ಕಸ್ಟಮ್ಸ್‌ನೊಂದಿಗೆ ಸಂವಹನಕ್ಕಾಗಿ ಆಮದುದಾರರು ಮತ್ತು ರಫ್ತುದಾರರಿಗೆ ಅಗತ್ಯವಾಗಿದೆ",
  "benefits_of_icegate": "📋 ಐಸಿಇಗೇಟ್ ನೋಂದಣಿಯ ಪ್ರಯೋಜನಗಳು:",
  "icegate_benefit_1": "• ಸುಗಮಗೊಂಡ ಕಸ್ಟಮ್ಸ್ ಕ್ಲಿಯರೆನ್ಸ್ ಪ್ರಕ್ರಿಯೆ",
  "icegate_benefit_2": "• ಆಮದು ಮತ್ತು ರಫ್ತು ರವಾನೆಗಳ ತ್ವರಿತ ಪ್ರಕ್ರಿಯೆ",
  "icegate_benefit_3": "• ಕಸ್ಟಮ್ಸ್ ಡೇಟಾ ಮತ್ತು ಸ್ಥಿತಿ ನವೀಕರಣಗಳಿಗೆ ಆನ್‌ಲೈನ್ ಪ್ರವೇಶ",
  "icegate_benefit_4": "• ಕಡಿಮೆ ಕಾಗದದ ಕೆಲಸ ಮತ್ತು ಹಸ್ತಚಾಲಿತ ಹಸ್ತಕ್ಷೇಪ",
  "icegate_benefit_5": "• ವ್ಯಾಪಾರ ಕಾರ್ಯಾಚರಣೆಗಳಲ್ಲಿ ವರ್ಧಿತ ಪಾರದರ್ಶಕತೆ ಮತ್ತು ದಕ್ಷತೆ",
  "icegate_application_submitted_processing": "ನಿಮ್ಮ ಐಸಿಇಗೇಟ್ ನೋಂದಣಿ ಅರ್ಜಿಯನ್ನು ಸಲ್ಲಿಸಲಾಗಿದೆ ಮತ್ತು ಪ್ರಸ್ತುತ ಪ್ರಕ್ರಿಯೆಯಲ್ಲಿದೆ. ನೀವು ಪ್ರಗತಿಯನ್ನು ಪ್ರಗತಿ ವಿಭಾಗದಲ್ಲಿ ಟ್ರ್ಯಾಕ್ ಮಾಡಬಹುದು.",
