  "what_is_adcode": "💰 ಎಡಿ ಕೋಡ್ ಎಂದರೇನು?",
  "adcode_definition_1": "• ಅಧಿಕೃತ ಡೀಲರ್ ಕೋಡ್ ಒಂದು ವಿಶಿಷ್ಟ ಗುರುತಿನ ಸಂಖ್ಯೆ",
  "adcode_definition_2": "• ವಿದೇಶಿ ವಿನಿಮಯ ವಹಿವಾಟುಗಳಿಗಾಗಿ ಅಧಿಕೃತ ಡೀಲರ್ ಬ್ಯಾಂಕ್‌ಗಳಿಂದ ಜಾರಿಗೊಳಿಸಲಾಗುತ್ತದೆ",
  "adcode_definition_3": "• ಆಮದು/ರಫ್ತು ವಹಿವಾಟುಗಳಿಗೆ ಮತ್ತು ವಿದೇಶಿ ರವಾನೆಗಳಿಗೆ ಅಗತ್ಯವಾಗಿದೆ",
  "adcode_definition_4": "• ಫಾರೆಕ್ಸ್ ಅನುಸರಣೆಗಾಗಿ ನಿಮ್ಮ ವ್ಯಾಪಾರವನ್ನು ಬ್ಯಾಂಕ್‌ನೊಂದಿಗೆ ಸಂಯೋಜಿಸುತ್ತದೆ",
  "adcode_definition_5": "• ಕಸ್ಟಮ್ಸ್ ಕ್ಲಿಯರೆನ್ಸ್ ಮತ್ತು ಆರ್‌ಬಿಐ ವರದಿಗಾಗಿ ಅಗತ್ಯವಾಗಿದೆ",
  "benefits_of_adcode": "📋 ಎಡಿ ಕೋಡ್‌ನ ಪ್ರಯೋಜನಗಳು:",
  "adcode_benefit_1": "• ಆಮದು/ರಫ್ತಿಗಾಗಿ ವಿದೇಶಿ ವಿನಿಮಯ ವಹಿವಾಟುಗಳನ್ನು ಸಕ್ರಿಯಗೊಳಿಸುತ್ತದೆ",
  "adcode_benefit_2": "• ಕಸ್ಟಮ್ಸ್ ಕ್ಲಿಯರೆನ್ಸ್ ಪ್ರಕ್ರಿಯೆಗಳನ್ನು ಸುಗಮಗೊಳಿಸುತ್ತದೆ",
  "adcode_benefit_3": "• ಕ್ರೆಡಿಟ್ ಪತ್ರ (ಎಲ್‌ಸಿ) ತೆರೆಯಲು ಅಗತ್ಯವಾಗಿದೆ",
  "adcode_benefit_4": "• ಬ್ಯಾಂಕ್ ಗ್ಯಾರಂಟಿ ಮತ್ತು ಇತರ ವ್ಯಾಪಾರ ಆರ್ಥಿಕ ಸೌಲಭ್ಯಗಳನ್ನು ಸಕ್ರಿಯಗೊಳಿಸುತ್ತದೆ",
  "adcode_benefit_5": "• ಆರ್‌ಬಿಐ ನಿಯಮಗಳೊಂದಿಗೆ ಅನುಸರಣೆಯನ್ನು ಖಾತ್ರಿಪಡಿಸುತ್ತದೆ",
