  // FAQ Questions and Answers
  "faq_q1": "ਮੈਂ ਗੋਫਾਰਮਲੀਕਨੈਕਟ ਤੇ ਆਪਣਾ ਫਾਰਮ ਕਿਵੇਂ ਰਜਿਸਟਰ ਕਰਾਂ?",
  "faq_a1": "ਰਜਿਸਟ੍ਰੇਸ਼ਨ ਸਰਲ ਅਤੇ ਮੁਫਤ ਹੈ। 'ਸ਼ੁਰੂ ਕਰੋ' ਤੇ ਕਲਿੱਕ ਕਰੋ, ਆਪਣੇ ਮੁੱਢਲੇ ਫਾਰਮ ਵੇਰਵੇ ਭਰੋ, ਲੋੜੀਂਦੇ ਦਸਤਾਵੇਜ਼ ਅਪਲੋਡ ਕਰੋ, ਅਤੇ ਆਪਣਾ ਮੋਬਾਈਲ ਨੰਬਰ ਵੈਰੀਫਾਈ ਕਰੋ। ਸਾਡੀ ਟੀਮ 24 ਘੰਟਿਆਂ ਦੇ ਅੰਦਰ ਤੁਹਾਡੇ ਖਾਤੇ ਦੀ ਸਮੀਖਿਆ ਕਰੇਗੀ ਅਤੇ ਸਰਗਰਮ ਕਰੇਗੀ।",
  "faq_q2": "ਮੈਂ ਪਲੇਟਫਾਰਮ ਰਾਹੀਂ ਕਿਹੜੇ ਦਸਤਾਵੇਜ਼ ਫਾਈਲ ਕਰ ਸਕਦਾ ਹਾਂ?",
  "faq_a2": "ਤੁਸੀਂ ਸਾਰੇ ਪ੍ਰਮੁੱਖ ਖੇਤੀਬਾੜੀ ਦਸਤਾਵੇਜ਼ ਫਾਈਲ ਕਰ ਸਕਦੇ ਹੋ ਜਿਸ ਵਿੱਚ ਫਸਲ ਬੀਮਾ ਅਰਜ਼ੀਆਂ, ਸਬਸਿਡੀ ਫਾਰਮ, ਲੋਨ ਅਰਜ਼ੀਆਂ, ਜ਼ਮੀਨ ਦੇ ਰਿਕਾਰਡ, ਮਿੱਟੀ ਸਿਹਤ ਕਾਰਡ, ਅਤੇ ਪਾਲਣਾ ਸਰਟੀਫਿਕੇਟ ਸ਼ਾਮਲ ਹਨ। ਸਾਡਾ ਸਿਸਟਮ 50+ ਤੋਂ ਵੱਧ ਦਸਤਾਵੇਜ਼ ਕਿਸਮਾਂ ਦਾ ਸਮਰਥਨ ਕਰਦਾ ਹੈ।",
  "faq_q3": "ਕੀ ਮੇਰਾ ਡੇਟਾ ਗੋਫਾਰਮਲੀਕਨੈਕਟ ਤੇ ਸੁਰੱਖਿਅਤ ਹੈ?",
  "faq_a3": "ਬਿਲਕੁਲ। ਅਸੀਂ ਬੈਂਕ-ਗ੍ਰੇਡ ਐਨਕ੍ਰਿਪਸ਼ਨ ਅਤੇ ਸਖਤ ਡੇਟਾ ਸੁਰੱਖਿਆ ਪ੍ਰੋਟੋਕੋਲ ਦੀ ਪਾਲਣਾ ਕਰਦੇ ਹਾਂ। ਤੁਹਾਡੀ ਜਾਣਕਾਰੀ ਸੁਰੱਖਿਅਤ ਢੰਗ ਨਾਲ ਸਟੋਰ ਕੀਤੀ ਜਾਂਦੀ ਹੈ ਅਤੇ ਤੁਹਾਡੀ ਸਹਿਮਤੀ ਤੋਂ ਬਿਨਾਂ ਕਿਸੇ ਤੀਜੀ ਧਿਰ ਨਾਲ ਸਾਂਝੀ ਨਹੀਂ ਕੀਤੀ ਜਾਂਦੀ। ਅਸੀਂ ਸਾਰੇ ਸਰਕਾਰੀ ਡੇਟਾ ਸੁਰੱਖਿਆ ਨਿਯਮਾਂ ਦੀ ਪਾਲਣਾ ਵੀ ਕਰਦੇ ਹਾਂ।",
  "faq_q4": "ਫਸਲ ਝਾੜ ਦੀਆਂ ਪੂਰਵਅਨੁਮਾਨਾਂ ਦੀ ਸ਼ੁੱਧਤਾ ਕਿੰਨੀ ਹੈ?",
  "faq_a4": "ਸਾਡੀਆਂ ਏਆਈ-ਸੰਚਾਲਿਤ ਪੂਰਵਅਨੁਮਾਨਾਂ ਦੀ ਸ਼ੁੱਧਤਾ ਦਰ 85-90% ਹੈ। ਅਸੀਂ ਸੈਟੇਲਾਈਟ ਚਿੱਤਰ, ਮੌਸਮ ਡੇਟਾ, ਮਿੱਟੀ ਦੀਆਂ ਸਥਿਤੀਆਂ, ਅਤੇ ਇਤਿਹਾਸਕ ਪੈਟਰਨਾਂ ਦੀ ਵਰਤੋਂ ਕਰਕੇ ਭਰੋਸੇਯੋਗ ਪੂਰਵਅਨੁਮਾਨ ਪ੍ਰਦਾਨ ਕਰਦੇ ਹਾਂ। ਹਾਲਾਂਕਿ, ਪੂਰਵਅਨੁਮਾਨਾਂ ਨੂੰ ਤੁਹਾਡੀ ਕਿਸਾਨੀ ਮੁਹਾਰਤ ਦੇ ਨਾਲ ਮਾਰਗਦਰਸ਼ਨ ਵਜੋਂ ਵਰਤਿਆ ਜਾਣਾ ਚਾਹੀਦਾ ਹੈ।",
  "faq_q5": "ਕੀ ਮੈਂ ਗੋਫਾਰਮਲੀਕਨੈਕਟ ਨੂੰ ਔਫਲਾਈਨ ਵਰਤ ਸਕਦਾ ਹਾਂ?",
  "faq_a5": "ਹਾਂ, ਸਾਡੀ ਮੋਬਾਈਲ ਐਪ ਵਿੱਚ ਔਫਲਾਈਨ ਸਮਰੱਥਾਵਾਂ ਹਨ। ਤੁਸੀਂ ਬਿਨਾਂ ਇੰਟਰਨੈਟ ਦੇ ਆਪਣਾ ਡੇਟਾ ਵੇਖ ਸਕਦੇ ਹੋ, ਫਾਰਮ ਭਰ ਸਕਦੇ ਹੋ, ਅਤੇ ਟਿਊਟੋਰੀਅਲ ਤੱਕ ਪਹੁੰਚ ਕਰ ਸਕਦੇ ਹੋ। ਜਦੋਂ ਤੁਸੀਂ ਦੁਬਾਰਾ ਔਨਲਾਈਨ ਹੋਵੋਗੇ, ਸਾਰੀਆਂ ਤਬਦੀਲੀਆਂ ਸਵੈਚਾਲਤ ਤੌਰ ਤੇ ਕਲਾਊਡ ਨਾਲ ਸਿੰਕ ਹੋ ਜਾਣਗੀਆਂ।",
  "faq_q6": "ਇਸ ਵਿੱਚ ਕੀ ਖਰਚੇ ਸ਼ਾਮਲ ਹਨ?",
  "faq_a6": "ਸਾਰੇ ਕਿਸਾਨਾਂ ਲਈ ਮੁਢਲੀਆਂ ਵਿਸ਼ੇਸ਼ਤਾਵਾਂ ਪੂਰੀ ਤਰ੍ਹਾਂ ਮੁਫਤ ਹਨ। ਉੱਨਤ ਵਿਸ਼ਲੇਸ਼ਣ, ਪ੍ਰਾਇਓਰਿਟੀ ਸਹਾਇਤਾ, ਅਤੇ ਵਾਧੂ ਸਟੋਰੇਜ ਵਰਗੀਆਂ ਪ੍ਰੀਮੀਅਮ ਵਿਸ਼ੇਸ਼ਤਾਵਾਂ 99 ਰੁਪਏ/ਮਹੀਨੇ ਤੋਂ ਸ਼ੁਰੂ ਹੋਣ ਵਾਲੀਆਂ ਕਿਫਾਇਤੀ ਸਬਸਕ੍ਰਿਪਸ਼ਨ ਯੋਜਨਾਵਾਂ ਰਾਹੀਂ ਉਪਲਬਧ ਹਨ।",
  "faq_q7": "ਮੈਂ ਤਕਨੀਕੀ ਸਹਾਇਤਾ ਕਿਵੇਂ ਪ੍ਰਾਪਤ ਕਰ ਸਕਦਾ ਹਾਂ?",
  "faq_a7": "ਅਸੀਂ 24/7 ਸਹਾਇਤਾ ਕਈ ਚੈਨਲਾਂ ਰਾਹੀਂ ਪ੍ਰਦਾਨ ਕਰਦੇ ਹਾਂ - ਫੋਨ (1800-3010-1000), ਈਮੇਲ, ਲਾਈਵ ਚੈਟ, ਅਤੇ ਵਟਸਐਪ। ਸਾਡੇ ਖੇਤੀਬਾੜੀ ਮਾਹਰ ਕਿਸੇ ਵੀ ਤਕਨੀਕੀ ਜਾਂ ਖੇਤੀਬਾੜੀ-ਸਬੰਧਤ ਪੁੱਛਗਿੱਛ ਵਿੱਚ ਤੁਹਾਡੀ ਮਦਦ ਲਈ ਹਮੇਸ਼ਾ ਤਿਆਰ ਹਨ।",
  "faq_q8": "ਕੀ ਮੈਂ ਗੋਫਾਰਮਲੀਕਨੈਕਟ ਨੂੰ ਹੋਰ ਖੇਤੀ ਸਾਧਨਾਂ ਨਾਲ ਜੋੜ ਸਕਦਾ ਹਾਂ?",
  "faq_a8": "ਹਾਂ, ਗੋਫਾਰਮਲੀਕਨੈਕਟ ਪ੍ਰਸਿੱਧ ਖੇਤੀ ਸਾਜ਼ੋ-ਸਾਮਾਨ, ਮੌਸਮ ਸਟੇਸ਼ਨਾਂ, ਅਤੇ ਵਿੱਤੀ ਸੇਵਾਵਾਂ ਨਾਲ ਜੁੜਦਾ ਹੈ। ਸਾਡੇ ਕੋਲ ਕਸਟਮ ਏਕੀਕਰਣ ਅਤੇ ਪ੍ਰਮੁੱਖ ਖੇਤੀਬਾੜੀ ਤਕਨਾਲੋਜੀ ਪ੍ਰਦਾਤਾਵਾਂ ਨਾਲ ਸਾਂਝੇਦਾਰੀ ਲਈ ਏਪੀਆਈ ਉਪਲਬਧ ਹਨ।",

