  // IEC Information
  "what_is_iec": "ਆਈਈਸੀ ਕੀ ਹੈ?",
  "iec_description_1": "ਆਈਈਸੀ (ਆਯਾਤ ਨਿਰਯਾਤ ਕੋਡ) ਡੀਜੀਐਫਟੀ ਦੁਆਰਾ ਜਾਰੀ ਕੀਤਾ ਗਿਆ 10-ਅੰਕੀ ਅਲਫਾਨਿਊਮਰਿਕ ਕੋਡ ਹੈ।",
  "iec_description_2": "ਇਹ ਭਾਰਤ ਵਿੱਚ ਆਯਾਤ ਜਾਂ ਨਿਰਯਾਤ ਕਾਰੋਬਾਰ ਵਿੱਚ ਸ਼ਾਮਲ ਵਿਅਕਤੀਆਂ/ਸੰਸਥਾਵਾਂ ਲਈ ਅਨਿਵਾਰਜ ਹੈ।",
  "iec_description_3": "ਕਸਟਮਜ਼ ਕਲੀਅਰੈਂਸ, ਵਿਦੇਸ਼ੀ ਮੁਦਰਾ ਲੈਣ-ਦੇਣ, ਅਤੇ ਅੰਤਰਰਾਸ਼ਟਰੀ ਵਪਾਰ ਲਈ ਲੋੜੀਂਦਾ।",
  "iec_description_4": "ਜੀਵਨ ਭਰ ਲਈ ਵੈਧ, ਕੋਈ ਨਵੀਨੀਕਰਨ ਦੀ ਲੋੜ ਨਹੀਂ।",
  "benefits_of_iec_registration": "ਆਈਈਸੀ ਰਜਿਸਟ੍ਰੇਸ਼ਨ ਦੇ ਲਾਭ:",
  "iec_benefit_1": "ਅੰਤਰਰਾਸ਼ਟਰੀ ਵਪਾਰ ਕਾਰਵਾਈਆਂ (ਆਯਾਤ ਅਤੇ ਨਿਰਯਾਤ) ਨੂੰ ਸਮਰੱਥ ਬਣਾਉਂਦਾ ਹੈ।",
  "iec_benefit_2": "ਡੀਜੀਐਫਟੀ ਤੋਂ ਨਿਰਯਾਤ ਪ੍ਰੋਤਸਾਹਨ ਅਤੇ ਸਕੀਮਾਂ ਤੱਕ ਪਹੁੰਚ।",
  "iec_benefit_3": "ਕਸਟਮਜ਼ ਪ੍ਰਕਿਰਿਆਵਾਂ ਅਤੇ ਦਸਤਾਵੇਜ਼ ਨੂੰ ਸਰਲ ਬਣਾਉਂਦਾ ਹੈ।",
  "iec_benefit_4": "ਗਲੋਬਲ ਮਾਰਕੀਟ ਵਿੱਚ ਕਾਰੋਬਾਰ ਦੀ ਵਿਸ਼ਵਸਨੀਯਤਾ ਵਧਾਉਂਦਾ ਹੈ।",
  "iec_benefit_5": "ਕੋਈ ਸਾਲਾਨਾ ਪਾਲਣਾ ਜਾਂ ਫਾਈਲਿੰਗ ਜ਼ਰੂਰਤਾਂ ਨਹੀਂ।",
  "dsc_definition_1": "ਡਿਜੀਟਲ ਸਿਗਨੇਚਰ ਸਰਟੀਫਿਕੇਟ ਇੱਕ ਸੁਰੱਖਿਅਤ ਡਿਜੀਟਲ ਕੁੰਜੀ ਹੈ",
  dsc_definition_2: "ഡിജിറ്റൽ ഇടപാടുകളിൽ നിന്റെ തിരിച്ചറിയൽ സാധൂകരിക്കാൻ ഉപയോഗിക്കുന്നു",
dsc_definition_3: "വിവിധ സർക്കാർ ഫോമുകളും രേഖകളും ഫയൽ ചെയ്യാൻ ആവശ്യമാണ്",
dsc_definition_4: "ഇലക്ട്രോണിക് രേഖകൾക്ക് നിയമപരമായ സാധുത നൽകുന്നു",
dsc_definition_5: "ജിഎസ്ടി റിട്ടേൺസ്, ആദായനികുതി ഫയലിംഗ് എന്നിവയ്ക്കും മറ്റും അത്യാവശ്യമാണ്",
uses_of_dsc: "ഡിഎസ്‌സിയുടെ ഉപയോഗങ്ങൾ:",
dsc_use_1: "ജിഎസ്ടി റിട്ടേൺസും മറ്റ് നികുതി രേഖകളും ഫയൽ ചെയ്യൽ",
dsc_use_2: "ഇ-ടെൻഡറിംഗും സർക്കാർ സംഭരണവും",
dsc_use_3: "കമ്പനി രജിസ്ട്രേഷനും പാലന ഫയലിംഗുകളും",
dsc_use_4: "ബാങ്കിംഗും ധനകാര്യ ഇടപാടുകളും",
dsc_use_5: "നിയമപരമായ രേഖ സാധൂകരണം",
important_notes: "പ്രധാന കുറിപ്പുകൾ:",
dsc_note_1: "ഡിഎസ്‌സി സാധാരണയായി ഇഷ്യൂ തീയതി മുതൽ 1-3 വർഷം വരെ സാധുവാണ്",
dsc_note_2: "നിനക്ക് ഡിഎസ്‌സി ഒരു യുഎസ്ബി ടോക്കണിലോ സോഫ്റ്റ്‌വെയർ സർട്ടിഫിക്കറ്റായോ ലഭിക്കും",
dsc_note_3: "നിന്റെ ഡിഎസ്‌സി പാസ്‌വേഡ് സുരക്ഷിതവും രഹസ്യവും ആയി സൂക്ഷിക്കുക",
dsc_note_4: "തുടർച്ചയായ ഉപയോഗത്തിന് കാലാവധി തീരുന്നതിന് മുമ്പ് പുതുക്കൽ ആവശ്യമാണ്",
dsc_application_submitted_processing:
  "നിന്റെ ഡിഎസ്‌സി രജിസ്ട്രേഷൻ അപേക്ഷ സമർപ്പിക്കപ്പെട്ടു, ഇപ്പോൾ പ്രോസസ്സിംഗിലാണ്. നിനക്ക് പുരോഗതി വിഭാഗത്തിൽ പുരോഗതി ട്രാക്ക് ചെയ്യാം.",
submit_dsc_application: "ഡിഎസ്‌സി അപേക്ഷ സമർപ്പിക്കുക ({{progress}}% പൂർത്തിയായി)",
