from_iec_registration: "ഐഇസി രജിസ്ട്രേഷനിൽ നിന്ന്",
what_is_icegate: "🌐 എന്താണ് ഐസിഗേറ്റ്?",
icegate_definition_1: "• ഇന്ത്യൻ കസ്റ്റംസ് ഇലക്ട്രോണിക് ഗേറ്റ്‌വേ ഒരു വ്യാപാര, കസ്റ്റംസ് ക്ലിയറൻസ് പോർട്ടലാണ്",
icegate_definition_2:
  "• വിവിധ കസ്റ്റംസ് രേഖകൾക്ക് ഇ-ഫയലിംഗ് സേവനങ്ങൾ നൽകുന്നു (ഉദാ: ബിൽ ഓഫ് എൻട്രി, ഷിപ്പിംഗ് ബിൽ)",
icegate_definition_3: "• കസ്റ്റംസ് ഡ്യൂട്ടികളുടെയും മറ്റ് ചാർജുകളുടെയും ഓൺലൈൻ പേയ്‌മെന്റ് സുഗമമാക്കുന്നു",
icegate_definition_4: "• ഇന്ത്യൻ കസ്റ്റംസുമായി ഇടപെടാൻ ഇറക്കുമതിക്കാർക്കും കയറ്റുമതിക്കാർക്കും അത്യാവശ്യമാണ്",
benefits_of_icegate: "📋 ഐസിഗേറ്റ് രജിസ്ട്രേഷന്റെ പ്രയോജനങ്ങൾ:",
icegate_benefit_1: "• കസ്റ്റംസ് ക്ലിയറൻസ് പ്രക്രിയ ലളിതമാക്കുന്നു",
icegate_benefit_2: "• ഇറക്കുമതി, കയറ്റുമതി കൺസൈൻമെന്റുകളുടെ വേഗത്തിലുള്ള പ്രോസസ്സിംഗ്",
icegate_benefit_3: "• കസ്റ്റംസ് ഡാറ്റയിലേക്കും സ്റ്റാറ്റസ് അപ്‌ഡേറ്റുകളിലേക്കും ഓൺലൈൻ ആക്സസ്",
icegate_benefit_4: "• കടലാസ് ജോലികളും മാനുവൽ ഇടപെടലും കുറയ്ക്കുന്നു",
icegate_benefit_5: "• വ്യാപാര പ്രവർത്തനങ്ങളിൽ സുതാര്യതയും കാര്യക്ഷമതയും വർദ്ധിപ്പിക്കുന്നു",
icegate_application_submitted_processing:
  "നിന്റെ ഐസിഗേറ്റ് രജിസ്ട്രേഷൻ അപേക്ഷ സമർപ്പിക്കപ്പെട്ടു, ഇപ്പോൾ പ്രോസസ്സിംഗിലാണ്. നിനക്ക് പുരോഗതി വിഭാഗത്തിൽ പുരോഗതി ട്രാക്ക് ചെയ്യാം.",
