cancelled_cheque_verification:
  "അക്കൗണ്ട് പരിശോധനയ്ക്കായി ഒരു റദ്ദാക്കിയ ചെക്ക്, ബാങ്ക് സ്റ്റേറ്റ്മെന്റ്, അല്ലെങ്കിൽ പാസ്ബുക്കിന്റെ മുൻപേജ് അപ്‌ലോഡ് ചെയ്യുക.",
what_is_adcode: "💰 എന്താണ് എഡി കോഡ്?",
adcode_definition_1: "• ഓതറൈസ്ഡ് ഡീലർ കോഡ് ഒരു അതുല്യമായ ഐഡന്റിഫിക്കേഷൻ നമ്പറാണ്",
adcode_definition_2: "• വിദേശ വിനിമയ ഇടപാടുകൾക്കായി ഓതറൈസ്ഡ് ഡീലർ ബാങ്കുകൾ നൽകുന്നു",
adcode_definition_3: "• ഇറക്കുമതി/കയറ്റുമതി ഇടപാടുകൾക്കും വിദേശ റെമിറ്റൻസുകൾക്കും ആവശ്യമാണ്",
adcode_definition_4: "• ഫോറെക്സ് പാലനത്തിനായി നിന്റെ ബിസിനസിനെ ബാങ്കുമായി ബന്ധിപ്പിക്കുന്നു",
adcode_definition_5: "• കസ്റ്റംസ് ക്ലിയറൻസിനും ആർബിഐ റിപ്പോർട്ടിംഗിനും അത്യാവശ്യമാണ്",
benefits_of_adcode: "📋 എഡി കോഡിന്റെ പ്രയോജനങ്ങൾ:",
adcode_benefit_1: "• ഇറക്കുമതി/കയറ്റുമതിക്കുള്ള വിദേശ വിനിമയ ഇടപാടുകൾ പ്രവർത്തനക്ഷമമാക്കുന്നു",
adcode_benefit_2: "• കസ്റ്റംസ് ക്ലിയറൻസ് പ്രക്രിയകൾ സുഗമമാക്കുന്നു",
adcode_benefit_3: "• ലെറ്റർ ഓഫ് ക്രെഡിറ്റ് (എൽസി) തുറക്കാൻ ആവശ്യമാണ്",
adcode_benefit_4: "• ബാങ്ക് ഗ്യാരന്റിയും മറ്റ് ട്രേഡ് ഫിനാൻസ് സൗകര്യങ്ങളും പ്രവർത്തനക്ഷമമാക്കുന്നു",
