  "empowering_farmers": "ਆਧੁਨਿਕ ਖੇਤੀਬਾੜੀ ਲਈ ਅਤਿ-ਆਧੁਨਿਕ ਡਿਜੀਟਲ ਹੱਲਾਂ ਨਾਲ ਕਿਸਾਨਾਂ ਨੂੰ ਸਸ਼ਕਤ ਕਰਨਾ। ਅੱਜ ਹੀ ਖੇਤੀ ਕ੍ਰਾਂਤੀ ਵਿੱਚ ਸ਼ਾਮਲ ਹੋਵੋ।",

  // FAQ Questions and Answers
  "faq_q1": "ਮੈਂ ਗੋਫਾਰਮਲੀਕਨੈਕਟ 'ਤੇ ਆਪਣਾ ਖੇਤ ਕਿਵੇਂ ਰਜਿਸਟਰ ਕਰਾਂ?",
  "faq_a1": "ਰਜਿਸਟ੍ਰੇਸ਼ਨ ਸਰਲ ਅਤੇ ਮੁਫਤ ਹੈ। 'ਸ਼ੁਰੂ ਕਰੋ' 'ਤੇ ਕਲਿੱਕ ਕਰੋ, ਆਪਣੇ ਮੁੱਢਲੇ ਖੇਤ ਵੇਰਵੇ ਭਰੋ, ਲੋੜੀਂਦੇ ਦਸਤਾਵੇਜ਼ ਅਪਲੋਡ ਕਰੋ, ਅਤੇ ਆਪਣਾ ਮੋਬਾਈਲ ਨੰਬਰ ਵੈਰੀਫਾਈ ਕਰੋ। ਸਾਡੀ ਟੀਮ 24 ਘੰਟਿਆਂ ਦੇ ਅੰਦਰ ਤੁਹਾਡੇ ਖਾਤੇ ਦੀ ਸਮੀਖਿਆ ਅਤੇ ਸਰਗਰਮ ਕਰੇਗੀ।",
  "faq_q2": "ਮੈਂ ਪਲੇਟਫਾਰਮ ਰਾਹੀਂ ਕਿਹੜੇ ਦਸਤਾਵੇਜ਼ ਫਾਈਲ ਕਰ ਸਕਦਾ ਹਾਂ?",
  "faq_a2": "ਤੁਸੀਂ ਸਾਰੇ ਪ੍ਰਮੁੱਖ ਖੇਤੀਬਾੜੀ ਦਸਤਾਵੇਜ਼ ਜਿਵੇਂ ਕਿ ਫਸਲ ਬੀਮਾ ਅਰਜ਼ੀਆਂ, ਸਬਸਿਡੀ ਫਾਰਮ, ਲੋਨ ਅਰਜ਼ੀਆਂ, ਜ਼ਮੀਨ ਦੇ ਰਿਕਾਰਡ, ਮਿੱਟੀ ਸਿਹਤ ਕਾਰਡ, ਅਤੇ ਪਾਲਣਾ ਸਰਟੀਫਿਕੇਟ ਫਾਈਲ ਕਰ ਸਕਦੇ ਹੋ। ਸਾਡਾ ਸਿਸਟਮ 50+ ਤੋਂ ਵੱਧ ਦਸਤਾਵੇਜ਼ ਕਿਸਮਾਂ ਦਾ ਸਮਰਥਨ ਕਰਦਾ ਹੈ।",
  "faq_q3": "ਕੀ ਮੇਰਾ ਡੇਟਾ ਗੋਫਾਰਮਲੀਕਨੈਕਟ 'ਤੇ ਸੁਰੱਖਿਅਤ ਹੈ?",
  "faq_a3": "ਬਿਲਕੁਲ। ਅਸੀਂ ਬੈਂਕ-ਗਰੇਡ ਐਨਕ੍ਰਿਪਸ਼ਨ ਅਤੇ ਸਖਤ ਡੇਟਾ ਸੁਰੱਖਿਆ ਪ੍ਰੋਟੋਕੋਲ ਦੀ ਪਾਲਣਾ ਕਰਦੇ ਹਾਂ। ਤੁਹਾਡੀ ਜਾਣਕਾਰੀ ਸੁਰੱਖਿਅਤ ਢੰਗ ਨਾਲ ਸਟੋਰ ਕੀਤੀ ਜਾਂਦੀ ਹੈ ਅਤੇ ਤੁਹਾਡੀ ਸਹਿਮਤੀ ਬਿਨਾਂ ਕਿਸੇ ਤੀਜੀ ਧਿਰ ਨਾਲ ਸਾਂਝੀ ਨਹੀਂ ਕੀਤੀ ਜਾਂਦੀ। ਅਸੀਂ ਸਾਰੇ ਸਰਕਾਰੀ ਡੇਟਾ ਸੁਰੱਖਿਆ ਨਿਯਮਾਂ ਦੀ ਪਾਲਣਾ ਵੀ ਕਰਦੇ ਹਾਂ।",
  "faq_q4": "ਫਸਲ ਝਾੜ ਅਨੁਮਾਨ ਕਿੰਨੇ ਸਹੀ ਹਨ?",
  "faq_a4": "ਸਾਡੇ AI-ਸੰਚਾਲਿਤ ਅਨੁਮਾਨਾਂ ਦੀ ਸਟੀਕਤਾ ਦਰ 85-90% ਹੈ। ਅਸੀਂ ਸੈਟੇਲਾਈਟ ਚਿੱਤਰ, ਮੌਸਮ ਡੇਟਾ, ਮਿੱਟੀ ਦੀਆਂ ਸਥਿਤੀਆਂ, ਅਤੇ ਇਤਿਹਾਸਕ ਪੈਟਰਨਾਂ ਦੀ ਵਰਤੋਂ ਕਰਕੇ ਭਰੋਸੇਯੋਗ ਪੂਰਵ-ਅਨੁਮਾਨ ਪ੍ਰਦਾਨ ਕਰਦੇ ਹਾਂ। ਹਾਲਾਂਕਿ, ਅਨੁਮਾਨਾਂ ਨੂੰ ਤੁਹਾਡੀ ਖੇਤੀ ਮੁਹਾਰਤ ਦੇ ਨਾਲ ਮਾਰਗਦਰਸ਼ਨ ਵਜੋਂ ਵਰਤਿਆ ਜਾਣਾ ਚਾਹੀਦਾ ਹੈ।",
  "faq_q5": "ਕੀ ਮੈਂ ਗੋਫਾਰਮਲੀਕਨੈਕਟ ਨੂੰ ਔਫਲਾਈਨ ਵਰਤ ਸਕਦਾ ਹਾਂ?",
  "faq_a5": "ਹਾਂ, ਸਾਡੀ ਮੋਬਾਈਲ ਐਪ ਵਿੱਚ ਔਫਲਾਈਨ ਸਮਰੱਥਾਵਾਂ ਹਨ। ਤੁਸੀਂ ਇੰਟਰਨੈਟ ਤੋਂ ਬਿਨਾਂ ਆਪਣਾ ਡੇਟਾ ਵੇਖ ਸਕਦੇ ਹੋ, ਫਾਰਮ ਭਰ ਸਕਦੇ ਹੋ, ਅਤੇ ਟਿਊਟੋਰੀਅਲ ਤੱਕ ਪਹੁੰਚ ਕਰ ਸਕਦੇ ਹੋ। ਜਦੋਂ ਤੁਸੀਂ ਵਾਪਸ ਔਨਲਾਈਨ ਹੁੰਦੇ ਹੋ, ਸਾਰੀਆਂ ਤਬਦੀਲੀਆਂ ਸਵੈਚਲਿਤ ਤੌਰ 'ਤੇ ਕਲਾਉਡ ਨਾਲ ਸਿੰਕ ਹੋ ਜਾਂਦੀਆਂ ਹਨ।",
  "faq_q6": "ਇਸ ਵਿੱਚ ਕਿੰਨੀ ਲਾਗਤ ਸ਼ਾਮਲ ਹੈ?",
  "faq_a6": "ਸਾਰੇ ਕਿਸਾਨਾਂ ਲਈ ਮੁੱਢਲੀਆਂ ਵਿਸ਼ੇਸ਼ਤਾਵਾਂ ਪੂਰੀ ਤਰ੍ਹਾਂ ਮੁਫਤ ਹਨ। ਉੱਨਤ ਵਿਸ਼ਲੇਸ਼ਣ, ਪ੍ਰਾਥਮਿਕਤਾ ਸਮਰਥਨ, ਅਤੇ ਵਾਧੂ ਸਟੋਰੇਜ ਵਰਗੀਆਂ ਪ੍ਰੀਮੀਅਮ ਵਿਸ਼ੇਸ਼ਤਾਵਾਂ ਸਸਤੀ ਸਬਸਕ੍ਰਿਪਸ਼ਨ ਯੋਜਨਾਵਾਂ ਰਾਹੀਂ 99 ਰੁਪਏ/ਮਹੀਨੇ ਤੋਂ ਸ਼ੁਰੂ ਹੁੰਦੀਆਂ ਹਨ।",
  "faq_q7": "ਮੈਂ ਤਕਨੀਕੀ ਸਮਰਥਨ ਕਿਵੇਂ ਪ੍ਰਾਪਤ ਕਰ ਸਕਦਾ ਹਾਂ?",
  "faq_a7": "ਅਸੀਂ ਕਈ ਚੈਨਲਾਂ - ਫੋਨ (1800-3010-1000), ਈਮੇਲ, ਲਾਈਵ ਚੈਟ, ਅਤੇ ਵਟਸਐਪ ਰਾਹੀਂ 24/7 ਸਮਰਥਨ ਦੀ ਪੇਸ਼ਕਸ਼ ਕਰਦੇ ਹਾਂ। ਸਾਡੇ ਖੇਤੀਬਾੜੀ ਮਾਹਰ ਕਿਸੇ ਵੀ ਤਕਨੀਕੀ ਜਾਂ ਖੇਤੀ-ਸੰਬੰਧੀ ਸਵਾਲਾਂ ਵਿੱਚ ਤੁਹਾਡੀ ਮਦਦ ਲਈ ਹਮੇਸ਼ਾ ਤਿਆਰ ਹਨ।",
  "faq_q8": "ਕੀ ਮੈਂ ਗੋਫਾਰਮਲੀਕਨੈਕਟ ਨੂੰ ਹੋਰ ਖੇਤੀ ਸੰਦਾਂ ਨਾਲ ਜੋੜ ਸਕਦਾ ਹਾਂ?",
  "faq_a8": "ਹਾਂ, ਗੋਫਾਰਮਲੀਕਨੈਕਟ ਪ੍ਰਸਿੱਧ ਖੇਤੀ ਉਪਕਰਣਾਂ, ਮੌਸਮ ਸਟੇਸ਼ਨਾਂ, ਅਤੇ ਵਿੱਤੀ ਸੇਵਾਵਾਂ ਨਾਲ ਜੁੜਦਾ ਹੈ। ਸਾਡੇ ਕੋਲ ਕਸਟਮ ਏਕੀਕਰਣ ਅਤੇ ਪ੍ਰਮੁੱਖ ਖੇਤੀਬਾੜੀ ਤਕਨੀਕ ਪ੍ਰਦਾਤਾਵਾਂ ਨਾਲ ਸਾਂਝੇਦਾਰੀ ਲਈ API ਉਪਲਬਧ ਹਨ।",

