  "iec_description_2": "ਇਹ ਭਾਰਤ ਵਿੱਚ ਆਯਾਤ ਜਾਂ ਨਿਰਯਾਤ ਕਾਰੋਬਾਰ ਵਿੱਚ ਸ਼ਾਮਲ ਵਿਅਕਤੀਆਂ/ਸੰਸਥਾਵਾਂ ਲਈ ਲਾਜ਼ਮੀ ਹੈ।",
