  "what_is_icegate": "🌐 ਆਈਸੀਈਗੇਟ ਕੀ ਹੈ?",
  "icegate_definition_1": "• ਇੰਡੀਅਨ ਕਸਟਮਜ਼ ਇਲੈਕਟ੍ਰਾਨਿਕ ਗੇਟਵੇ ਵਪਾਰ ਅਤੇ ਕਸਟਮਜ਼ ਕਲੀਅਰੈਂਸ ਲਈ ਇੱਕ ਪੋਰਟਲ ਹੈ",
  "icegate_definition_2": "• ਵੱਖ-ਵੱਖ ਕਸਟਮਜ਼ ਦਸਤਾਵੇਜ਼ਾਂ (ਜਿਵੇਂ, ਐਂਟਰੀ ਦਾ ਬਿੱਲ, ਸ਼ਿਪਿੰਗ ਬਿੱਲ) ਲਈ ਈ-ਫਾਈਲਿੰਗ ਸੇਵਾਵਾਂ ਪ੍ਰਦਾਨ ਕਰਦਾ ਹੈ",
  "icegate_definition_3": "• ਕਸਟਮਜ਼ ਡਿਊਟੀਆਂ ਅਤੇ ਹੋਰ ਚਾਰਜਿਜ਼ ਦੇ ਔਨਲਾਈਨ ਭੁਗਤਾਨ ਦੀ ਸਹੂਲਤ ਦਿੰਦਾ ਹੈ",
  "icegate_definition_4": "• ਭਾਰਤੀ ਕਸਟਮਜ਼ ਨਾਲ ਸੰਪਰਕ ਕਰਨ ਲਈ ਆਯਾਤਕਾਰਾਂ ਅਤੇ ਨਿਰਯਾਤਕਾਰਾਂ ਲਈ ਜ਼ਰੂਰੀ",
  "benefits_of_icegate": "📋 ਆਈਸੀਈਗੇਟ ਰਜਿਸਟ੍ਰੇਸ਼ਨ ਦੇ ਲਾਭ:",
  "icegate_benefit_1": "• ਸੁਚਾਰੂ ਕਸਟਮਜ਼ ਕਲੀਅਰੈਂਸ ਪ੍ਰਕਿਰਿਆ",
  "icegate_benefit_2": "• ਆਯਾਤ ਅਤੇ ਨਿਰਯਾਤ ਸ਼ਿਪਮੈਂਟਸ ਦੀ ਤੇਜ਼ ਪ੍ਰੋਸੈਸਿੰਗ",
  "icegate_benefit_3": "• ਕਸਟਮਜ਼ ਡੇਟਾ ਅਤੇ ਸਥਿਤੀ ਅਪਡੇਟਸ ਤੱਕ ਔਨਲਾਈਨ ਪਹੁੰਚ",
  "icegate_benefit_4": "• ਕਾਗਜ਼ੀ ਕਾਰਵਾਈ ਅਤੇ ਮੈਨੂਅਲ ਦਖਲਅੰਦਾਜ਼ੀ ਵਿੱਚ ਕਮੀ",
  "icegate_benefit_5": "• ਵਪਾਰਕ ਕਾਰਜਾਂ ਵਿੱਚ ਵਧੀ ਹੋਈ ਪਾਰਦਰਸ਼ਤਾ ਅਤੇ ਕੁਸ਼ਲਤਾ",
  "icegate_application_submitted_processing": "ਤੁਹਾਡੀ ਆਈਸੀਈਗੇਟ ਰਜਿਸਟ੍ਰੇਸ਼ਨ ਅਰਜ਼ੀ ਜਮ੍ਹਾਂ ਕਰ ਦਿੱਤੀ ਗਈ ਹੈ ਅਤੇ ਵਰਤਮਾਨ ਵਿੱਚ ਪ੍ਰੋਸੈਸ ਹੋ ਰਹੀ ਹੈ। ਤੁਸੀਂ ਪ੍ਰਗਤੀ ਨੂੰ ਪ੍ਰਗਤੀ ਸੈਕਸ਼ਨ ਵਿੱਚ ਟਰੈਕ ਕਰ ਸਕਦੇ ਹੋ।",
