  "what_is_adcode": "💰 ਏਡੀ ਕੋਡ ਕੀ ਹੈ?",
  "adcode_definition_1": "• ਅਧਿਕਾਰਤ ਡੀਲਰ ਕੋਡ ਇੱਕ ਵਿਲੱਖਣ ਪਛਾਣ ਨੰਬਰ ਹੈ",
  "adcode_definition_2": "• ਵਿਦੇਸ਼ੀ ਮੁਦਰਾ ਲੈਣ-ਦੇਣ ਲਈ ਅਧਿਕਾਰਤ ਡੀਲਰ ਬੈਂਕਾਂ ਦੁਆਰਾ ਜਾਰੀ ਕੀਤਾ ਜਾਂਦਾ ਹੈ",
  "adcode_definition_3": "• ਆਯਾਤ/ਨਿਰਯਾਤ ਲੈਣ-ਦੇਣ ਅਤੇ ਵਿਦੇਸ਼ੀ ਰੈਮਿਟੈਂਸ ਲਈ ਲੋੜੀਂਦਾ",
  "adcode_definition_4": "• ਤੁਹਾਡੇ ਕਾਰੋਬਾਰ ਨੂੰ ਫਾਰੈਕਸ ਪਾਲਣਾ ਲਈ ਬੈਂਕ ਨਾਲ ਜੋੜਦਾ ਹੈ",
  "adcode_definition_5": "• ਕਸਟਮਜ਼ ਕਲੀਅਰੈਂਸ ਅਤੇ ਆਰਬੀਆਈ ਰਿਪੋਰਟਿੰਗ ਲਈ ਜ਼ਰੂਰੀ",
  "benefits_of_adcode": "📋 ਏਡੀ ਕੋਡ ਦੇ ਲਾਭ:",
  "adcode_benefit_1": "• ਆਯਾਤ/ਨਿਰਯਾਤ ਲਈ ਵਿਦੇਸ਼ੀ ਮੁਦਰਾ ਲੈਣ-ਦੇਣ ਸਮਰੱਥ ਕਰਦਾ ਹੈ",
  "adcode_benefit_2": "• ਕਸਟਮਜ਼ ਕਲੀਅਰੈਂਸ ਪ੍ਰਕਿਰਿਆਵਾਂ ਦੀ ਸਹੂਲਤ ਦਿੰਦਾ ਹੈ",
  "adcode_benefit_3": "• ਲੈਟਰ ਆਫ ਕ੍ਰੈਡਿਟ (ਐਲਸੀ) ਖੋਲ੍ਹਣ ਲਈ ਲੋੜੀਂਦਾ",
  "adcode_benefit_4": "• ਬੈਂਕ ਗਾਰੰਟੀ ਅਤੇ ਹੋਰ ਵਪਾਰਕ ਵਿੱਤ ਸਹੂਲਤਾਂ ਸਮਰੱਥ ਕਰਦਾ ਹੈ",
  "adcode_benefit_5": "• ਆਰਬੀਆਈ ਨਿਯਮਾਂ ਦੀ ਪਾਲਣਾ ਨੂੰ ਯਕੀਨੀ ਬਣਾਉਂਦਾ ਹੈ",
  "adcode_application_submitted_processing": "ਤੁਹਾਡੀ ਏਡੀ ਕੋਡ ਰਜਿਸਟ੍ਰੇਸ਼ਨ ਅਰਜ਼ੀ ਜਮ੍ਹਾਂ ਕਰ ਦਿੱਤੀ ਗਈ ਹੈ ਅਤੇ ਵਰਤਮਾਨ ਵਿੱਚ ਪ੍ਰੋਸੈਸ ਹੋ ਰਹੀ ਹੈ। ਤੁਸੀਂ ਪ੍ਰਗਤੀ ਨੂੰ ਪ੍ਰਗਤੀ ਸੈਕਸ਼ਨ ਵਿੱਚ ਟਰੈਕ ਕਰ ਸਕਦੇ ਹੋ।",
