    "copyright_text": "© 2025 ਗੋਫਾਰਮਲੀਕਨੈਕਟ - ਤਕਨੀਕ ਰਾਹੀਂ ਖੇਤੀਬਾੜੀ ਨੂੰ ਬਦਲਣਾ। ਸਾਰੇ ਅਧਿਕਾਰ ਸੁਰੱਖਿਅਤ।",
    "made_with_love": "ਕਿਸਾਨਾਂ ਲਈ ❤️ ਨਾਲ ਬਣਾਇਆ",
    "proudly_indian": "🇮🇳 ਮਾਣ ਨਾਲ ਭਾਰਤੀ",
    "serving_farmers": "ਭਾਰਤ ਭਰ ਵਿੱਚ ਕਿਸਾਨਾਂ ਦੀ ਸੇਵਾ",
    "empowering_farmers": "ਆਧੁਨਿਕ ਖੇਤੀਬਾੜੀ ਲਈ ਅਤਿ-ਆਧੁਨਿਕ ਡਿਜੀਟਲ ਹੱਲਾਂ ਨਾਲ ਕਿਸਾਨਾਂ ਨੂੰ ਸਸ਼ਕਤ ਕਰਨਾ। ਅੱਜ ਖੇਤੀ ਕ੍ਰਾਂਤੀ ਵਿੱਚ ਸ਼ਾਮਲ ਹੋਵੋ।",
    "faq_q1": "ਮੈਂ ਗੋਫਾਰਮਲੀਕਨੈਕਟ 'ਤੇ ਆਪਣਾ ਖੇਤ ਕਿਵੇਂ ਰਜਿਸਟਰ ਕਰਾਂ?",
    "faq_a1": "ਰਜਿਸਟ੍ਰੇਸ਼ਨ ਸਰਲ ਅਤੇ ਮੁਫਤ ਹੈ। 'ਸ਼ੁਰੂ ਕਰੋ' 'ਤੇ ਕਲਿੱਕ ਕਰੋ, ਆਪਣੇ ਮੁੱਢਲੇ ਖੇਤ ਦੇ ਵੇਰਵੇ ਭਰੋ, ਲੋੜੀਂਦੇ ਦਸਤਾਵੇਜ਼ ਅਪਲੋਡ ਕਰੋ, ਅਤੇ ਆਪਣਾ ਮੋਬਾਈਲ ਨੰਬਰ ਪ੍ਰਮਾਣਿਤ ਕਰੋ। ਸਾਡੀ ਟੀਮ 24 ਘੰਟਿਆਂ ਦੇ ਅੰਦਰ ਤੁਹਾਡੇ ਖਾਤੇ ਦੀ ਸਮੀਖਿਆ ਅਤੇ ਸਰਗਰਮ ਕਰੇਗੀ।",
    "faq_q2": "ਮੈਂ ਪਲੇਟਫਾਰਮ ਰਾਹੀਂ ਕਿਹੜੇ ਦਸਤਾਵੇਜ਼ ਫਾਈਲ ਕਰ ਸਕਦਾ ਹਾਂ?",
    "faq_a2": "ਤੁਸੀਂ ਸਾਰੇ ਮੁੱਖ ਖੇਤੀਬਾੜੀ ਦਸਤਾਵੇਜ਼ ਫਾਈਲ ਕਰ ਸਕਦੇ ਹੋ ਜਿਸ ਵਿੱਚ ਫਸਲ ਬੀਮਾ ਅਰਜ਼ੀਆਂ, ਸਬਸਿਡੀ ਫਾਰਮ, ਲੋਨ ਅਰਜ਼ੀਆਂ, ਜ਼ਮੀਨ ਦੇ ਰਿਕਾਰਡ, ਮਿੱਟੀ ਸਿਹਤ ਕਾਰਡ, ਅਤੇ ਪਾਲਣਾ ਸਰਟੀਫਿਕੇਟ ਸ਼ਾਮਲ ਹਨ। ਸਾਡਾ ਸਿਸਟਮ 50+ ਤੋਂ ਵੱਧ ਦਸਤਾਵੇਜ਼ ਕਿਸਮਾਂ ਨੂੰ ਸਮਰਥਨ ਦਿੰਦਾ ਹੈ।",
    "faq_q3": "ਕੀ ਮੇਰਾ ਡੇਟਾ ਗੋਫਾਰਮਲੀਕਨੈਕਟ 'ਤੇ ਸੁਰੱਖਿਅਤ ਹੈ?",
    "faq_a3": "ਬਿਲਕੁਲ। ਅਸੀਂ ਬੈਂਕ-ਗਰੇਡ ਐਨਕ੍ਰਿਪਸ਼ਨ ਅਤੇ ਸਖਤ ਡੇਟਾ ਸੁਰੱਖਿਆ ਪ੍ਰੋਟੋਕੋਲ ਦੀ ਪਾਲਣਾ ਕਰਦੇ ਹਾਂ। ਤੁਹਾਡੀ ਜਾਣਕਾਰੀ ਸੁਰੱਖਿਅਤ ਢੰਗ ਨਾਲ ਸਟੋਰ ਕੀਤੀ ਜਾਂਦੀ ਹੈ ਅਤੇ ਤੁਹਾਡੀ ਸਹਿਮਤੀ ਬਿਨਾਂ ਕਿਸੇ ਤੀਜੀ ਧਿਰ ਨਾਲ ਸਾਂਝੀ ਨਹੀਂ ਕੀਤੀ ਜਾਂਦੀ। ਅਸੀਂ ਸਾਰੇ ਸਰਕਾਰੀ ਡੇਟਾ ਸੁਰੱਖਿਆ ਨਿਯਮਾਂ ਦੀ ਵੀ ਪਾਲਣਾ ਕਰਦੇ ਹਾਂ।",
    "faq_q4": "ਫਸਲ ਉਤਪਾਦਨ ਦੀਆਂ ਭਵਿੱਖਬਾਣੀਆਂ ਕਿੰਨੀਆਂ ਸਹੀ ਹਨ?",
    "faq_a4": "ਸਾਡੀਆਂ ਏਆਈ-ਸੰਚਾਲਿਤ ਭਵਿੱਖਬਾਣੀਆਂ ਦੀ ਸਹੀਤਾ ਦਰ 85-90% ਹੈ। ਅਸੀਂ ਸੈਟੇਲਾਈਟ ਚਿੱਤਰ, ਮੌਸਮ ਡੇਟਾ, ਮਿੱਟੀ ਦੀਆਂ ਸਥਿਤੀਆਂ, ਅਤੇ ਇਤਿਹਾਸਕ ਪੈਟਰਨਾਂ ਦੀ ਵਰਤੋਂ ਕਰਕੇ ਭਰੋਸੇਮੰਦ ਪੂਰਵਅਨੁਮਾਨ ਪ੍ਰਦਾਨ ਕਰਦੇ ਹਾਂ। ਹਾਲਾਂਕਿ, ਭਵਿੱਖਬਾਣੀਆਂ ਨੂੰ ਤੁਹਾਡੀ ਖੇਤੀ ਮੁਹਾਰਤ ਦੇ ਨਾਲ ਸਲਾਹ ਵਜੋਂ ਵਰਤਿਆ ਜਾਣਾ ਚਾਹੀਦਾ ਹੈ।",
    "faq_q5": "ਕੀ ਮੈਂ ਗੋਫਾਰਮਲੀਕਨੈਕਟ ਨੂੰ ਆਫਲਾਈਨ ਵਰਤ ਸਕਦਾ ਹਾਂ?",
    "faq_a5": "ਹਾਂ, ਸਾਡੀ ਮੋਬਾਈਲ ਐਪ ਵਿੱਚ ਆਫਲਾਈਨ ਸਮਰੱਥਾਵਾਂ ਹਨ। ਤੁਸੀਂ ਇੰਟਰਨੈਟ ਤੋਂ ਬਿਨਾਂ ਆਪਣਾ ਡੇਟਾ ਵੇਖ ਸਕਦੇ ਹੋ, ਫਾਰਮ ਭਰ ਸਕਦੇ ਹੋ, ਅਤੇ ਟਿਊਟੋਰੀਅਲਸ ਤੱਕ ਪਹੁੰਚ ਕਰ ਸਕਦੇ ਹੋ। ਜਦੋਂ ਤੁਸੀਂ ਵਾਪਸ ਆਨਲਾਈਨ ਹੋਵੋਗੇ, ਸਾਰੀਆਂ ਤਬਦੀਲੀਆਂ ਸਵੈਚਾਲਿਤ ਤੌਰ 'ਤੇ ਕਲਾਉਡ ਨਾਲ ਸਿੰਕ ਹੋ ਜਾਂਦੀਆਂ ਹਨ।",
    "faq_q6": "ਇਸ ਵਿੱਚ ਕੀ ਖਰਚੇ ਸ਼ਾਮਲ ਹਨ?",
    "faq_a6": "ਸਾਰੇ ਕਿਸਾਨਾਂ ਲਈ ਮੁੱਢਲੀਆਂ ਵਿਸ਼ੇਸ਼ਤਾਵਾਂ ਪੂਰੀ ਤਰ੍ਹਾਂ ਮੁਫਤ ਹਨ। ਉੱਨਤ ਵਿਸ਼ਲੇਸ਼ਣ, ਪ੍ਰਾਇਓਰਿਟੀ ਸਹਾਇਤਾ, ਅਤੇ ਵਾਧੂ ਸਟੋਰੇਜ ਵਰਗੀਆਂ ਪ੍ਰੀਮੀਅਮ ਵਿਸ਼ੇਸ਼ਤਾਵਾਂ 99 ਰੁਪਏ/ਮਹੀਨੇ ਤੋਂ ਸ਼ੁਰੂ ਹੋਣ ਵਾਲੀਆਂ ਸਸਤੀ ਸਬਸਕ੍ਰਿਪਸ਼ਨ ਯੋਜਨਾਵਾਂ ਰਾਹੀਂ ਉਪਲਬਧ ਹਨ।",
    "faq_q7": "ਮੈਂ ਤਕਨੀਕੀ ਸਹਾਇਤਾ ਕਿਵੇਂ ਪ੍ਰਾਪਤ ਕਰ ਸਕਦਾ ਹਾਂ?",
    "faq_a7": "ਅਸੀਂ ਕਈ ਚੈਨਲਾਂ ਰਾਹੀਂ 24/7 ਸਹਾਇਤਾ ਪ੍ਰਦਾਨ ਕਰਦੇ ਹਾਂ - ਫੋਨ (1800-3010-1000), ਈਮੇਲ, ਲਾਈਵ ਚੈਟ, ਅਤੇ ਵਟਸਐਪ। ਸਾਡੇ ਖੇਤੀਬਾੜੀ ਮਾਹਰ ਕਿਸੇ ਵੀ ਤਕਨੀਕੀ ਜਾਂ ਖੇਤੀ ਸੰਬੰਧੀ ਸਵਾਲਾਂ ਵਿੱਚ ਤੁਹਾਡੀ ਮਦਦ ਲਈ ਹਮੇਸ਼ਾ ਤਿਆਰ ਹਨ।",
    "faq_q8": "ਕੀ ਮੈਂ ਗੋਫਾਰਮਲੀਕਨੈਕਟ ਨੂੰ ਹੋਰ ਖੇਤੀ ਸੰਦਾਂ ਨਾਲ ਜੋੜ ਸਕਦਾ ਹਾਂ?",
    "faq_a8": "ਹਾਂ, ਗੋਫਾਰਮਲੀਕਨੈਕਟ ਪ੍ਰਸਿੱਧ ਖੇਤੀ ਉਪਕਰਨਾਂ, ਮੌਸਮ ਸਟੇਸ਼ਨਾਂ, ਅਤੇ ਵਿੱਤੀ ਸੇਵਾਵਾਂ ਨਾਲ ਜੁੜਦਾ ਹੈ। ਸਾਡੇ ਕੋਲ ਕਸਟਮ ਏਕੀਕਰਨ ਅਤੇ ਪ੍ਰਮੁੱਖ ਖੇਤੀਬਾੜੀ ਤਕਨੀਕ ਪ੍ਰਦਾਤਾਵਾਂ ਨਾਲ ਸਾਂਝੇਦਾਰੀ ਲਈ API ਉਪਲਬਧ ਹਨ।",
