  "adcode_definition_3": "• ਆਯਾਤ/ਨਿਰਯਾਤ ਲੈਣ-ਦੇਣ ਅਤੇ ਵਿਦੇਸ਼ੀ ਰੈਮਿਟੈਂਸ ਲਈ ਲੋੜੀਂਦਾ",
