    "faq_q1": "میں اپنا فارم گوفارملی کنیکٹ پر کیسے رجسٹر کروں؟",
    "faq_a1": "رجسٹریشن آسان اور مفت ہے۔ 'شروع کریں' پر کلک کریں، اپنی بنیادی فارم کی تفصیلات بھریں، مطلوبہ دستاویزات اپ لوڈ کریں، اور اپنا موبائل نمبر تصدیق کریں۔ ہماری ٹیم 24 گھنٹوں کے اندر آپ کا اکاؤنٹ جائزہ لے گی اور فعال کرے گی۔",
    "faq_q2": "میں پلیٹ فارم کے ذریعے کون سی دستاویزات فائل کر سکتا ہوں؟",
    "faq_a2": "آپ فصل کی انشورنس درخواستوں، سبسڈی فارمز، قرض کی درخواستوں، زمین کے ریکارڈز، مٹی کی صحت کارڈز، اور تعمیل کے سرٹیفکیٹس سمیت تمام بڑی زرعی دستاویزات فائل کر سکتے ہیں۔ ہمارا نظام 50 سے زیادہ دستاویزات کی اقسام کو سپورٹ کرتا ہے۔",
    "faq_q3": "کیا میرا ڈیٹا گوفارملی کنیکٹ پر محفوظ ہے؟",
    "faq_a3": "بالکل۔ ہم بینک گریڈ انکرپشن استعمال کرتے ہیں اور سخت ڈیٹا پروٹیکشن پروٹوکولز کی پیروی کرتے ہیں۔ آپ کی معلومات محفوظ طریقے سے محفوظ کی جاتی ہیں اور آپ کی رضامندی کے بغیر کبھی بھی تیسرے فریق کے ساتھ شیئر نہیں کی جاتیں۔ ہم تمام حکومتی ڈیٹا پروٹیکشن ضوابط کے ساتھ بھی تعمیل کرتے ہیں۔",
    "faq_q4": "فصل کی پیداوار کی پیش گوئیاں کتنی درست ہیں؟",
    "faq_a4": "ہماری AI سے چلنے والی پیش گوئیاں 85-90 فیصد درستگی کی شرح رکھتی ہیں۔ ہم سیٹلائٹ تصاویر، موسم کے ڈیٹا، مٹی کے حالات، اور تاریخی پیٹرن کا استعمال کرکے قابل اعتماد پیش گوئیاں فراہم کرتے ہیں۔ تاہم، پیش گوئیاں آپ کی زرعی مہارت کے ساتھ رہنمائی کے طور پر استعمال کی جانی چاہئیں۔",
    "faq_q5": "کیا میں گوفارملی کنیکٹ کو آف لائن استعمال کر سکتا ہوں؟",
    "faq_a5": "جی ہاں، ہماری موبائل ایپ میں آف لائن صلاحیتیں ہیں۔ آپ اپنا ڈیٹا دیکھ سکتے ہیں، فارمز بھر سکتے ہیں، اور بغیر انٹرنیٹ کے سبق تک رسائی حاصل کر سکتے ہیں۔ جب آپ دوبارہ آن لائن ہوں گے، تمام تبدیلیاں خود بخود کلاؤڈ کے ساتھ ہم آہنگ ہو جائیں گی۔",
    "faq_q6": "اس میں کتنی لاگت آتی ہے؟",
    "faq_a6": "تمام کسانوں کے لئے بنیادی خصوصیات مکمل طور پر مفت ہیں۔ جدید تجزیات، ترجیحی سپورٹ، اور اضافی اسٹوریج جیسے پریمیم خصوصیات ₹99/ماہ سے شروع ہونے والے سستی سبسکرپشن پلانز کے ذریعے دستیاب ہیں۔",
    "faq_q7": "میں تکنیکی سپورٹ کیسے حاصل کروں؟",
    "faq_a7": "ہم متعدد چینلز کے ذریعے 24/7 سپورٹ پیش کرتے ہیں - فون (1800-3010-1000)، ای میل، لائیو چیٹ، اور واٹس ایپ۔ ہمارے زرعی ماہرین کسی بھی تکنیکی یا زرعی سوالات کے ساتھ آپ کی مدد کے لئے ہمیشہ تیار ہیں۔",
    "faq_q8": "کیا میں گوفارملی کنیکٹ کو دیگر زرعی اوزاروں کے ساتھ مربوط کر سکتا ہوں؟",
    "faq_a8": "جی ہاں، گوفارملی کنیکٹ مشہور زرعی آلات، موسم کے اسٹیشنز، اور مالیاتی خدمات کے ساتھ مربوط ہوتا ہے۔ ہمارے پاس اپنی مرضی کے انٹیگریشنز اور بڑے زرعی ٹیکنالوجی فراہم کنندگان کے ساتھ شراکت داری کے لئے APIs دستیاب ہیں۔",
