    "dsc_note_3": "اپنے ڈی ایس سی پاس ورڈ کو محفوظ اور رازداری میں رکھیں",
    "dsc_note_4": "مسلسل استعمال کے لئے میعاد ختم ہونے سے پہلے تجدید کی ضرورت ہے",
    "dsc_application_submitted_processing": "آپ کی ڈی ایس سی رجسٹریشن درخواست جمع ہوگئی ہے اور فی الحال اس پر عملدرآمد ہو رہا ہے۔ آپ پیشرفت سیکشن میں پیشرفت کو ٹریک کر سکتے ہیں۔",
