    "what_is_icegate": "🌐 آئی سی ای گیٹ کیا ہے؟",
    "icegate_definition_1": "• انڈین کسٹمز الیکٹرانک گیٹ وے تجارت اور کسٹم کلیئرنس کے لئے ایک پورٹل ہے",
    "icegate_definition_2": "• مختلف کسٹم دستاویزات (جیسے، بل آف انٹری، شپنگ بل) کے لئے ای-فائلنگ خدمات فراہم کرتا ہے",
    "icegate_definition_3": "• کسٹم ڈیوٹی اور دیگر چارجز کی آن لائن ادائیگی کی سہولت دیتا ہے",
    "icegate_definition_4": "• درآمد کنندگان اور برآمد کنندگان کے لئے ہندوستانی کسٹمز کے ساتھ تعامل کے لئے ضروری ہے",
    "benefits_of_icegate": "📋 آئی سی ای گیٹ رجسٹریشن کے فوائد:",
    "icegate_benefit_1": "• ہموار کسٹم کلیئرنس عمل",
    "icegate_benefit_2": "• درآمد اور برآمد کے کنسائنمنٹس کی تیز پروسیسنگ",
    "icegate_benefit_3": "• کسٹم ڈیٹا اور حالت کی اپ ڈیٹس تک آن لائن رسائی",
    "icegate_benefit_4": "• کاغذی کارروائی اور دستی مداخلت کو کم کرتا ہے",
    "icegate_benefit_5": "• تجارت کے آپریشنز میں شفافیت اور کارکردگی کو بڑھاتا ہے",
